#include <CoreFoundation/CoreFoundation.h> // CFNumber, CFString (IOKit)
#include <IOKit/IOKitLib.h>           // IOServiceGetMatchingServices ...
#include <IOKit/IOCFPlugIn.h>         // IOCreatePlugInInterfaceForService
#include <IOKit/usb/IOUSBLib.h>       // USB device / interface interfaces
#include <AudioToolbox/AudioToolbox.h>// AudioQueue (audible feedback beeps)
#include <pthread.h>                  // Frame hand-over mutex and condition
#include <stdint.h>                   // uint8_t etc. (on Linux these come
#include <inttypes.h>                 // with the PulseAudio headers); PRIu8
#include <signal.h>                   // signal(SIGPIPE, SIG_IGN)
//---------------------------------------------------------------------------//.
 //                                  macOS                                  //.
  //-----------------------------------------------------------------------//.
#endif

#if IS_WINDOWS_NATIVE || defined(__APPLE__)
  //-----------------------------------------------------------------------\\.
 //          MS Windows and macOS: the V4L2 codes used by this program      \\.
//---------------------------------------------------------------------------\\.
// The program identifies image stream formats and camera controls by their
// V4L2 codes (they are written into camera settings files and appear in the
// shared GUI code). On Windows and macOS there is no <linux/videodev2.h>, so
// the codes this program uses are defined here with exactly the names and
// numeric values that <linux/videodev2.h> gives them. This is what makes
// camera settings files exchangeable between the three operating systems.
#define v4l2_fourcc(a,b,c,d) \
   (((unsigned int)(a)) | (((unsigned int)(b)) << 8) | \
   (((unsigned int)(c)) << 16) | (((unsigned int)(d)) << 24))
#define V4L2_PIX_FMT_YUYV    v4l2_fourcc('Y','U','Y','V') // 16 bpp YUV 4:2:2
#define V4L2_PIX_FMT_MJPEG   v4l2_fourcc('M','J','P','G') // Motion-JPEG
#define V4L2_PIX_FMT_GREY    v4l2_fourcc('G','R','E','Y') // 8 bpp greyscale
#define V4L2_PIX_FMT_Y10     v4l2_fourcc('Y','1','0',' ') // 10 bpp greyscale
#define V4L2_PIX_FMT_SGBRG10 v4l2_fourcc('G','B','1','0') // 10 bpp Bayer GBRG
#define V4L2_PIX_FMT_SRGGB10 v4l2_fourcc('R','G','1','0') // 10 bpp Bayer RGGB
// Camera control IDs (control class bases and the controls of the UVC
// standard that the Windows and macOS camera functions provide):
#define V4L2_CID_USER_CLASS                0x00980001
#define V4L2_CID_BRIGHTNESS                0x00980900
#define V4L2_CID_CONTRAST                  0x00980901
#define V4L2_CID_SATURATION                0x00980902
#define V4L2_CID_HUE                       0x00980903
#define V4L2_CID_AUTO_WHITE_BALANCE        0x0098090C
#define V4L2_CID_GAMMA                     0x00980910
#define V4L2_CID_AUTOGAIN                  0x00980912
#define V4L2_CID_GAIN                      0x00980913
#define V4L2_CID_POWER_LINE_FREQUENCY      0x00980918
#define V4L2_CID_HUE_AUTO                  0x00980919
#define V4L2_CID_WHITE_BALANCE_TEMPERATURE 0x0098091A
#define V4L2_CID_SHARPNESS                 0x0098091B
#define V4L2_CID_BACKLIGHT_COMPENSATION    0x0098091C
#define V4L2_CID_CAMERA_CLASS              0x009A0001
#define V4L2_CID_EXPOSURE_AUTO             0x009A0901
#define V4L2_CID_EXPOSURE_ABSOLUTE         0x009A0902
#define V4L2_CID_EXPOSURE_AUTO_PRIORITY    0x009A0903
#define V4L2_CID_PAN_ABSOLUTE              0x009A0908
#define V4L2_CID_TILT_ABSOLUTE             0x009A0909
#define V4L2_CID_FOCUS_ABSOLUTE            0x009A090A
#define V4L2_CID_FOCUS_AUTO                0x009A090C
#define V4L2_CID_ZOOM_ABSOLUTE             0x009A090D
#define V4L2_CID_IRIS_ABSOLUTE             0x009A0911
//---------------------------------------------------------------------------//.
 //          MS Windows and macOS: the V4L2 codes used by this program      //.
  //-----------------------------------------------------------------------//.
#endif
