#if IS_WINDOWS_NATIVE
int AudioInit()
// MS Windows version (14.11.26): opens the default audio output (WAVE_MAPPER)
// with the waveOut functions, in the same sample format as the Linux version
// uses with PulseAudio: 16-bit signed little-endian PCM, 44100 Hz, 2 channels.
{
 char msgtxt[MSGTXT_LEN];
 char errtxt[MAXERRORLENGTH];
 WAVEFORMATEX wfx;
 MMRESULT mr;

 if(Audio_status!=AS_NULL) return 1;

 memset(&wfx, 0, sizeof(wfx));
 wfx.wFormatTag      = WAVE_FORMAT_PCM;
 wfx.nChannels       = 2;
 wfx.nSamplesPerSec  = 44100;
 wfx.wBitsPerSample  = 16;
 wfx.nBlockAlign     = (WORD)(wfx.nChannels * wfx.wBitsPerSample / 8); // 4 bytes
 wfx.nAvgBytesPerSec = wfx.nSamplesPerSec * wfx.nBlockAlign;          // 176400
 wfx.cbSize          = 0;

 mr = waveOutOpen(&PA_hwo, WAVE_MAPPER, &wfx, 0, 0, CALLBACK_NULL);
 if(mr != MMSYSERR_NOERROR){
    if(waveOutGetErrorTextA(mr, errtxt, (UINT)sizeof(errtxt)) != MMSYSERR_NOERROR)
       snprintf(errtxt, sizeof(errtxt), "error %u", (unsigned int)mr);
    snprintf(msgtxt,sizeof(msgtxt),"waveOutOpen() failed: %s", errtxt);
    show_message(msgtxt,"AudioInit: ",MT_ERR,0);
    PA_hwo = NULL;
    return 1;
   }

 Audio_status=AS_INIT;
 return 0;
}
#elif defined(__APPLE__)
int AudioInit()
// macOS version (14.11.26): creates an AudioQueue for output in the same
// sample format as the Linux version uses with PulseAudio: 16-bit signed
// little-endian linear PCM, 44100 Hz, 2 interleaved channels.
{
 char msgtxt[MSGTXT_LEN];
 AudioStreamBasicDescription fmt;
 OSStatus st;

 if(Audio_status!=AS_NULL) return 1;

 memset(&fmt, 0, sizeof(fmt));
 fmt.mSampleRate       = 44100.0;
 fmt.mFormatID         = kAudioFormatLinearPCM;
 fmt.mFormatFlags      = kLinearPCMFormatFlagIsSignedInteger | kLinearPCMFormatFlagIsPacked;
 fmt.mChannelsPerFrame = 2;
 fmt.mBitsPerChannel   = 16;
 fmt.mBytesPerFrame    = 4;  // 2 channels x 2 bytes
 fmt.mFramesPerPacket  = 1;
 fmt.mBytesPerPacket   = 4;

 // The output callback is not needed (the one buffer is played once), so
 // a callback that does nothing is given; the queue runs on its own thread.
 st = AudioQueueNewOutput(&fmt, mac_aq_output_cb, NULL, NULL, NULL, 0, &PA_aq);
 if(st != noErr){
    snprintf(msgtxt,sizeof(msgtxt),"AudioQueueNewOutput() failed: error %d", (int)st);
    show_message(msgtxt,"AudioInit: ",MT_ERR,0);
    PA_aq = NULL;
    return 1;
   }

 Audio_status=AS_INIT;
 return 0;
}
#else // Linux (original version)
int AudioInit()
{
 char msgtxt[MSGTXT_LEN];
 int retval=0;
 int error;
 // The Sample format to use
 static const pa_sample_spec ss = {
     .format = PA_SAMPLE_S16LE,
     .rate = 44100,
     .channels = 2
 };

 if(Audio_status!=AS_NULL) return 1; 
 
 // Create a new playback stream 
 if (!(PA_s=pa_simple_new(NULL,"a_beep",PA_STREAM_PLAYBACK,NULL,"playback",&ss,NULL,NULL,&error))){
    snprintf(msgtxt,sizeof(msgtxt),"pa_simple_new() failed: %s", pa_strerror(error));
    show_message(msgtxt,"AudioInit: ",MT_ERR,0);
    retval=1;
  }

  if(retval==0) Audio_status=AS_INIT;
  return retval; 
}
#endif

#if IS_WINDOWS_NATIVE
int AudioUnInit(void)
// MS Windows version (14.11.26): closes the waveOut device opened by AudioInit.
{
  if(Audio_status!=AS_INIT) return 1;
  if(PA_hwo){
     waveOutReset(PA_hwo);  // Stops playback and returns any buffer
     waveOutClose(PA_hwo);
     PA_hwo = NULL;
    }
  Audio_status=AS_NULL;
  return 0;
}
#elif defined(__APPLE__)
int AudioUnInit(void)
// macOS version (14.11.26): disposes of the AudioQueue made by AudioInit.
{
  if(Audio_status!=AS_INIT) return 1;
  if(PA_aq){
     AudioQueueStop(PA_aq, true);      // Immediately
     AudioQueueDispose(PA_aq, true);   // Also frees its buffers
     PA_aq = NULL;
    }
  Audio_status=AS_NULL;
  return 0;
}
#else // Linux (original version)
int AudioUnInit(void)
{
  if(Audio_status!=AS_INIT) return 1; 
  if (PA_s) pa_simple_free(PA_s);
  Audio_status=AS_NULL; 
  return 0;
}
#endif

#if IS_WINDOWS_NATIVE
int a_beep(int duration, int pitch)
// Primitive beeper function.
// MS Windows version (14.11.26) using the waveOut functions of winmm.
// duration = duration of beep
// pitch = the octave: supply 0, 1, 2 or 3.
// The sound is the same as on Linux: the same PABUFSIZE-byte block, made from
// sine_buffer[] in the same way, is played 'duration' times in succession as
// 16-bit stereo PCM at 44100 Hz. PulseAudio is fed the block 'duration' times;
// here the blocks are placed one after another in a single buffer and played
// with one waveOutWrite(), and the function returns when Windows reports that
// the buffer has been played (the Linux version returns after pa_simple_drain()
// has waited for the end of playback).
{
 uint8_t *audiobuffer;
 uint8_t block[PABUFSIZE];
 int idx,sdx;
 size_t total;
 WAVEHDR hdr;
 DWORD play_ms, waited_ms;

if(Use_audio==AU_NO) return 0;
// One beep at a time. This stops multiple parallel threads
// executing the beep function.
if(Audio_sounding) return 0;
Audio_sounding=1;
// Initialise sound generating capability
 if(AudioInit()){Audio_sounding=0; return 1;}

 // One block, exactly as the Linux version makes it
 for( idx=sdx=0; idx<PABUFSIZE; idx++ ){
      block[idx]=sine_buffer[sdx];
      sdx+=pitch;
      if(sdx>=PABUFSIZE) sdx=0;
     }

 if(duration<20) duration =20;

 total=(size_t)duration*(size_t)PABUFSIZE;
 audiobuffer=(uint8_t *)malloc(total);
 if(audiobuffer==NULL){
   show_message("Failed to get memory for audio buffer.","a_beep: ",MT_ERR,0);
   AudioUnInit();
   Audio_sounding=0;
   return 1;
  }
 for(idx=0;idx<duration;idx++) memcpy(audiobuffer+(size_t)idx*PABUFSIZE, block, PABUFSIZE);

 memset(&hdr, 0, sizeof(hdr));
 hdr.lpData = (LPSTR)audiobuffer;
 hdr.dwBufferLength = (DWORD)total;
 if(waveOutPrepareHeader(PA_hwo, &hdr, sizeof(hdr)) != MMSYSERR_NOERROR){
    fprintf(stderr,"a_beep: waveOutPrepareHeader() failed\n");
    goto uninit_audio;
   }
 if(waveOutWrite(PA_hwo, &hdr, sizeof(hdr)) != MMSYSERR_NOERROR){
    fprintf(stderr,"a_beep: waveOutWrite() failed\n");
    waveOutUnprepareHeader(PA_hwo, &hdr, sizeof(hdr));
    goto uninit_audio;
   }

 // Playing time in ms = bytes / (44100 frames/s * 4 bytes/frame) * 1000.
 // Wait for the 'done' flag, with a generous limit in case the audio device
 // stops responding (then the playback is abandoned by waveOutReset).
 play_ms = (DWORD)((total * 1000u) / (44100u * 4u));
 for(waited_ms=0; !(hdr.dwFlags & WHDR_DONE) && waited_ms < play_ms + 2000u; waited_ms+=5)
    Sleep(5);
 if(!(hdr.dwFlags & WHDR_DONE)) waveOutReset(PA_hwo);
 waveOutUnprepareHeader(PA_hwo, &hdr, sizeof(hdr));

uninit_audio:
        AudioUnInit();
free(audiobuffer);
Audio_sounding=0;
 return 0;
}
#elif defined(__APPLE__)
int a_beep(int duration, int pitch)
// Primitive beeper function.
// macOS version (14.11.26) using AudioQueue.
// duration = duration of beep
// pitch = the octave: supply 0, 1, 2 or 3.
// The sound is the same as on Linux: the same PABUFSIZE-byte block, made from
// sine_buffer[] in the same way, is played 'duration' times in succession as
// 16-bit stereo PCM at 44100 Hz. The blocks are placed one after another in a
// single AudioQueue buffer, and the function returns when that buffer has
// been played (the Linux version returns after pa_simple_drain() has waited
// for the end of playback).
{
 uint8_t block[PABUFSIZE];
 int idx,sdx;
 size_t total;
 AudioQueueBufferRef qb = NULL;
 useconds_t play_us;

if(Use_audio==AU_NO) return 0;
// One beep at a time. This stops multiple parallel threads
// executing the beep function.
if(Audio_sounding) return 0;
Audio_sounding=1;
// Initialise sound generating capability
 if(AudioInit()){Audio_sounding=0; return 1;}

 // One block, exactly as the Linux version makes it
 for( idx=sdx=0; idx<PABUFSIZE; idx++ ){
      block[idx]=sine_buffer[sdx];
      sdx+=pitch;
      if(sdx>=PABUFSIZE) sdx=0;
     }

 if(duration<20) duration =20;
 total=(size_t)duration*(size_t)PABUFSIZE;

 if(AudioQueueAllocateBuffer(PA_aq, (UInt32)total, &qb) != noErr || qb == NULL){
    fprintf(stderr,"a_beep: AudioQueueAllocateBuffer() failed\n");
    goto uninit_audio;
   }
 for(idx=0;idx<duration;idx++)
    memcpy((uint8_t *)qb->mAudioData + (size_t)idx*PABUFSIZE, block, PABUFSIZE);
 qb->mAudioDataByteSize = (UInt32)total;

 if(AudioQueueEnqueueBuffer(PA_aq, qb, 0, NULL) != noErr){
    fprintf(stderr,"a_beep: AudioQueueEnqueueBuffer() failed\n");
    goto uninit_audio;
   }
 if(AudioQueueStart(PA_aq, NULL) != noErr){
    fprintf(stderr,"a_beep: AudioQueueStart() failed\n");
    goto uninit_audio;
   }
 // Playing time = bytes / (44100 frames/s * 4 bytes/frame). Wait for it, plus
 // 100 ms for the output latency of the audio hardware (the Linux version
 // also waits 100 ms before draining), then stop.
 play_us = (useconds_t)(((unsigned long long)total * 1000000ULL) / (44100ULL * 4ULL));
 usleep(play_us + 100000);
 AudioQueueStop(PA_aq, false);  // After what is queued has been played

uninit_audio:
        AudioUnInit();   // (AudioQueueDispose also frees the buffer)
Audio_sounding=0;
 return 0;
}
#else // Linux (original version)
int a_beep(int duration, int pitch)
// Primitive beeper function using PulseAudio-simple lib APIs.
// duration = duration of beep
// pitch = the octave: supply 0, 1, 2 or 3.
{
 uint8_t *audiobuffer;
 int idx,sdx;
 int error;

if(Use_audio==AU_NO) return 0;
// One beep at a time. This stops multiple parallel threads
// executing the beep function. A further safeguard is below.
if(Audio_sounding) return 0; 
Audio_sounding=1;
// Initialise sound generating capability
 if(AudioInit()){Audio_sounding=0; return 1;}

 audiobuffer=(uint8_t *)calloc((size_t)(PABUFSIZE),sizeof(uint8_t));
 if(audiobuffer==NULL){
   show_message("Failed to get memory for audio buffer.","a_beep: ",MT_ERR,0);  
   AudioUnInit();
   Audio_sounding=0;
   return 1;
  }

 for( idx=sdx=0; idx<PABUFSIZE; idx++ ){
      audiobuffer[idx]=sine_buffer[sdx];
      sdx+=pitch;
      if(sdx>=PABUFSIZE) sdx=0;
     }

 if(duration<20) duration =20;

 for(idx=0;idx<duration;idx++){
 if(pa_simple_write(PA_s,audiobuffer,(size_t)PABUFSIZE,&error)<0){
    fprintf(stderr,"pa_beep: pa_simple_write() failed: %s\n", pa_strerror(error));
    goto uninit_audio;
   }
   usleep(200);
  }
usleep(100000);
  if (pa_simple_drain(PA_s,&error)<0){
        fprintf(stderr, "pa_beep: pa_simple_drain() failed: %s\n", pa_strerror(error));
        goto uninit_audio;
    }
uninit_audio:
        AudioUnInit();
free(audiobuffer);
Audio_sounding=0;
 return 0;
}
#endif

