static void handle_preview_off_widgets(void)
// This is for when I need to switch off live previewing manually, e.g. after a
// camera disconnect error is detected.
{
 // Instantly abort if the GUI is down or already tearing down
 if (!gui_up) return;

 // This may have been called by the calling function but it won't hurt to do it
 // again here just in case:
 Need_to_preview=PREVIEW_OFF;

 // Update tracking labels
 if(Label_preview != NULL && GTK_IS_WIDGET(Label_preview)){
   gtk_label_set_text(GTK_LABEL(Label_preview), " Preview is OFF ");
   gtk_widget_set_visible(GTK_WIDGET(Label_preview), TRUE);
  }

 // Ensure the live preview box is un-ticked to maintain the GUI state machine
 // in the correct condition.
 // Verify that the checkbox widget pointer actively exists and is whole in RAM
 if(chk_cam_preview != NULL && GTK_IS_WIDGET(chk_cam_preview)){
   // Only modify the widget if it is currently checked (TRUE)
   if(gtk_check_button_get_active(GTK_CHECK_BUTTON(chk_cam_preview))){
     // Step A: Temporarily block the toggle callback from firing
     g_signal_handlers_block_by_func(chk_cam_preview,
                              G_CALLBACK(toggled_cam_preview), chk_cam_preview);
     // Step B: Uncheck the live preview check box
     gtk_check_button_set_active(GTK_CHECK_BUTTON(chk_cam_preview), FALSE);
     // Step C: Re-enable the signal immediately so manual user clicks will work
     g_signal_handlers_unblock_by_func(chk_cam_preview,
                              G_CALLBACK(toggled_cam_preview), chk_cam_preview);
    }
  }
 return;
}

static void toggled_cam_preview(GtkWidget *toggle_button,gpointer user_data)
{
 // If none of the supported formats are provided by the camera, you
 // cannot allow settings to be set:
 if(CAF_ALLBAD){
   show_message("You cannot preview because your camera does not support YUYV"
                " or MJPEG streaming. Restart the program with another camera.",
                                                             "FYI: ",MT_INFO,1);
   return;  
  }
 // Manual preview feature is disabled in these server modes.
 if(ps_ServerLevel>1 && ps_CliSrv_connected){
    gtk_check_button_set_active(GTK_CHECK_BUTTON(toggle_button),FALSE);
    return; 
   }

 if (gtk_check_button_get_active(GTK_CHECK_BUTTON(toggle_button))){
     preview_only_once = 1;
     Need_to_preview=PREVIEW_ON;
     if(Preview_fullsize)
         gtk_label_set_text(GTK_LABEL(Label_preview)," Click to zoom ");

     if(!(Preview_fullsize && Preview_tile_selection_made==0))
        gtk_widget_set_visible(GTK_WIDGET(Label_preview),FALSE);
 } else {
     Need_to_preview=PREVIEW_OFF;
     gtk_label_set_text(GTK_LABEL(Label_preview)," Preview is OFF ");
     gtk_widget_set_visible(GTK_WIDGET(Label_preview),TRUE);
 }
 return;
}

