void nullify_darkfield(void)
// Test if already nullified so return without doing anything. This is
// not just for efficiency but also to prevent un-necessary pop-ups and
// error messages when loading settings from a saved settings file.
{
 if(!strcmp(DFFile,"[None]")) return;
 
  resize_memblk((void **)&DF_Image,1,sizeof(unsigned char), "the dark field image");
  DFht=DFwd=0;
  sprintf(DFFile,"[None]");
  dffile_loaded = DFIMG_NONE;
  dfcorr_status = DFCORR_OFF;
  // GUI stuff - don't do this if the camera settings window is not
  // visible because the dynamically allocated GUI controls will not be
  // addressable and GTK errors will result. This situation may arise
  // during the running of a script if the camera settings window was
  // closed prior to running it.
  if(gtk_widget_is_visible(Win_cam_settings)==TRUE){
      gtk_check_button_set_active(GTK_CHECK_BUTTON(chk_usedfcor),FALSE);
      gtk_widget_set_sensitive (chk_usedfcor,FALSE);
      gtk_label_set_text(GTK_LABEL(CamsetWidget[windex_ud]),"No");
      gtk_widget_set_sensitive (CamsetWidget[windex_ud],FALSE);
      gtk_widget_set_sensitive (CamsetWidget[windex_ud2],FALSE);
      // Set label to show nullified filename
      gtk_label_set_text(GTK_LABEL(CamsetWidget[windex_rdfi]), DFFile);  
    }
  show_message("Any pre-existing dark field image has been nullified. Dark field subtraction is disabled till a new dark field image is loaded.","FYI: ",MT_INFO,1);
  return;
}

static int init_darkfield_image(void)
// Load and prepare any user-supplied dark-field image.
// Return 0 on success and 1 on failure
{
 int lht,lwd,imfmt,width_stride;
 size_t imsz,rgbimsz;
 char msgtxt[MSGTXT_LEN];
 imfmt=0; 
     
 // Read the image file header to get dimensions and file type
 if(read_qih_file(Selected_DF_filename,&lht,&lwd, &imfmt)){
    show_message("Selected dark field image(s) cannot be loaded. No dark field correction can be done. Try selecting another file.","FAILED: ",MT_ERR,1);
    nullify_darkfield(); return 1;
   }

 // Check dimensions are identical to current main image
 if(lht!=Selected_Ht){
    show_message("Selected dark field image is not the same height as main image. Cannot proceed.","FAILED: ",MT_ERR,1);
    nullify_darkfield(); return 1;
   }     
 if(lwd!=Selected_Wd){
    show_message("Selected dark field image is not the same width as main image. Cannot proceed.","FAILED: ",MT_ERR,1);
    nullify_darkfield(); return 1;
   }     

 // OK, now see if we can allocate memory for the dark field image
  switch(imfmt){
    case DFIMG_Y:
     width_stride=Selected_Wd;
    break;
    case DFIMG_RGB:
     width_stride=Selected_Wd*3;
    break;
    default: // This should not happen
        show_message("Unrecognised image format for dark field image.","Program Error: ",MT_ERR,1);
        nullify_darkfield();
        return 1;
    }
 imsz=(size_t)Selected_Ht*(size_t)width_stride; 
 rgbimsz=imsz;
 
 if(resize_memblk((void **)&DF_Image,rgbimsz,sizeof(double), "the dark field image"))
  {
   nullify_darkfield();
   return 1;
  }

 // We got memory, so now try reading the image into it
 snprintf(msgtxt,sizeof(msgtxt),"There was a problem reading the chosen dark field file. Cannot proceed.");
 if(read_raw_doubles(Selected_DF_filename, &DF_Image,lht,lwd,imfmt)){
    show_message(msgtxt,"FAILED: ",MT_ERR,1);
    nullify_darkfield(); return 1;
   }

    
 // OK. Image is loaded correctly. Now we set the dimensions and GUI:
 DFht=lht; DFwd=lwd;
 sprintf(DFFile,"%s",Selected_DF_filename);
 snprintf(msgtxt,sizeof(msgtxt),"Dark field correction image loaded: %s",DFFile);
 show_message(msgtxt,"FYI: ",MT_INFO,0);
 dffile_loaded=imfmt;
 if(gtk_widget_is_visible(Win_cam_settings)==TRUE){
     //set label to show filename
     gtk_label_set_text(GTK_LABEL(CamsetWidget[windex_rdfi]), name_from_path(DFFile));  
     gtk_widget_set_sensitive (chk_usedfcor,TRUE);
     gtk_widget_set_sensitive (CamsetWidget[windex_ud],TRUE);
     gtk_widget_set_sensitive (CamsetWidget[windex_ud2],TRUE);
  }
 
 return 0;
}

int test_selected_ff_filename(char *filename)
// Attempt to read the file header and see if it is suitable for use as a master
// flat for flat field correction. If successful, copy the file name into the
// global Selected_FF_filename variable and set the ff_pending flag and GUI
// widgets accordingly. 
// Return 0 on success, 1 on failure.
{
 char msgtxt[4202];
 int imfmt,lht,lwd;
 int16_t bitcount;
     
 // Read the image file header to get dimensions and file type
 imfmt=0;
 if(!get_pgm_header(filename, &lht,&lwd))     imfmt=SAF_YP5; // pgm greyscale
 else if(!get_ppm_header(filename, &lht,&lwd))imfmt=SAF_RGB; // ppm colour
 else if(!get_bmp_header(filename, &lht,&lwd,&bitcount)){// It's a bmp image:
        switch(bitcount){
            case 8: imfmt=SAF_BM8; break; // greyscale bmp
            case 24:imfmt=SAF_BMP; break; // colour    bmp  
            default:
             show_message("Selected flat field bmp image is not 8 or 24 bit"
              " (other bit depths are not supported). Select a different file.",
                                                       "FAILED: ",MT_ERR,1);
            return 1;
        }   
    } else {// It is not one of the allowed unsigned char formats so see if
            // it is a raw doubles flat field image:
         
            // Read the external qih file header to get dimensions and file type
            if(read_qih_file(filename,&lht,&lwd, &imfmt)){
              show_message("Selected flat field image(s) is not of an"
                           " acceptable format. Select a different file.",
                                                       "FAILED: ",MT_ERR,1);
              return 1;
             }
           }  
     
    sprintf(Selected_FF_filename,"%s",filename);
    ff_pending=1;
    
  if(gtk_widget_is_visible(Win_cam_settings)==TRUE){
    gtk_widget_set_sensitive (chk_useffcor,TRUE);
    gtk_widget_set_sensitive (CamsetWidget[windex_uf],TRUE);
    gtk_widget_set_sensitive (CamsetWidget[windex_uf2],TRUE);
   }

    snprintf(msgtxt,sizeof(msgtxt),"You selected flat field image: %s (%d)\nWill attempt to"
                   " load and process it when you click 'Apply'.",
                                    name_from_path(Selected_FF_filename),imfmt);
    show_message(msgtxt,"FYI: ",MT_INFO,1);
   return 0;
}

static void btn_cs_load_flatfield_click(GtkWidget *widget, gpointer data) 
// This just gets the file name and checks the format, it doesn't load the image
{
 GtkFileDialog *file_dialog;
 GListStore *filters;
 GtkFileFilter *dou_filter;
 GtkFileFilter *pgm_filter;
 GtkFileFilter *ppm_filter;
 GtkFileFilter *bmp_filter;

 ff_pending=0;
 
 // Set up the 'file load' dialogue with the flat field image choices
  // Create a GListStore to hold the filters
  filters = g_list_store_new (GTK_TYPE_FILE_FILTER);

  // Create the .pgm filter
  pgm_filter = gtk_file_filter_new ();
  gtk_file_filter_add_pattern (pgm_filter, "*.pgm");
  gtk_file_filter_set_name (pgm_filter, "pgm images");
  g_list_store_append (filters, pgm_filter); // Add to the list store
  g_object_unref(pgm_filter); // GListStore takes a reference

  // Create the .ppm filter
  ppm_filter = gtk_file_filter_new ();
  gtk_file_filter_add_pattern (ppm_filter, "*.ppm");
  gtk_file_filter_set_name (ppm_filter, "ppm images");
  g_list_store_append (filters, ppm_filter); // Add to the list store
  g_object_unref(ppm_filter); // GListStore takes a reference

  // Create the .bmp filter
  bmp_filter = gtk_file_filter_new ();
  gtk_file_filter_add_pattern (bmp_filter, "*.bmp");
  gtk_file_filter_set_name (bmp_filter, "bmp images");
  g_list_store_append (filters, bmp_filter); // Add to the list store
  g_object_unref(bmp_filter); // GListStore takes a reference

  // Create the .dou filter
  dou_filter = gtk_file_filter_new ();
  gtk_file_filter_add_pattern (dou_filter, "*.dou");
  gtk_file_filter_set_name (dou_filter, "Raw doubles images");
  g_list_store_append (filters, dou_filter); // Add to the list store
  g_object_unref(dou_filter); // GListStore takes a reference

  // Create the 'file load' dialogue  
  file_dialog = gtk_file_dialog_new ();
  // Set the filters list for the file_dialog
  gtk_file_dialog_set_filters (file_dialog, G_LIST_MODEL (filters));
  // Set the purpose of the dialog
  gtk_file_dialog_set_title(file_dialog, "Load a Flat Field Image");
  // Set the text for the primary action button ("Load").
  gtk_file_dialog_set_accept_label(file_dialog, "Load File");
  g_object_set(file_dialog, "modal", TRUE, NULL); // Ensure it's modal
  // Show the file_dialog
  gtk_file_dialog_open (file_dialog,
                        GTK_WINDOW (Win_main),
                        NULL,
                        (GAsyncReadyCallback) filedlg_callback,
                        GINT_TO_POINTER(FILEDLG_FLATFIELD));

  // Clean up / free the filters list store and file dialog
  g_object_unref(filters);
  g_object_unref(file_dialog); 
}

void nullify_flatfield(void)
 // Test if already nullified so return without doing anything. This is
 // not just for efficiency but also to prevent un-necessary pop-ups and
 // error messages when loading settings from a saved settings file.
{
 if(!strcmp(FFFile,"[None]")) return;
 
  resize_memblk((void **)&FF_Image,1,sizeof(unsigned char), "the flat field image");
  FFht=FFwd=0;
  sprintf(FFFile,"[None]");
  fffile_loaded = FFIMG_NONE;
  ffcorr_status = FFCORR_OFF;
  // GUI stuff - don't do this if the camera settings window is not visible
  // because the dynamically allocated GUI controls will not be addressable
  // and GTK errors will result. This situation may arise during the running
  // of a script if the camera settings window was closed prior to running it.
  if(gtk_widget_is_visible(Win_cam_settings)==TRUE){
      gtk_check_button_set_active(GTK_CHECK_BUTTON(chk_useffcor),FALSE);
      gtk_widget_set_sensitive (chk_useffcor,FALSE);
      gtk_label_set_text(GTK_LABEL(CamsetWidget[windex_uf]),"No");
      gtk_widget_set_sensitive (CamsetWidget[windex_uf],FALSE);
      gtk_widget_set_sensitive (CamsetWidget[windex_uf2],FALSE);
      // Set label to show nullified filename
      gtk_label_set_text(GTK_LABEL(CamsetWidget[windex_rffi]), FFFile);  
    }
  show_message("Any pre-existing flat field image has been nullified. Flat field correction is disabled till a new flat field image is loaded.","FYI: ",MT_INFO,1);
  return;
}

static int init_flatfield_image(int normalise_ff)
// Read and initialise any user-supplied flat field file.
// normalise_ff is a flag that tells the function whether to normalise the flat
// field image within the support of the mask (1) or not (0).
// This function is called twice when applying settings. The first time is to
// load an image and check its format and dimensions only (so is called with
// normalise_ff=0). The second time is after the user makes their selection of
// whether to apply a custom mask or not (and whether that custom mask is
// successfully loaded or fails with a full mask being substituted) so is called
// with normalise_ff=1).
// The above 'double call' system occurs when PARDcap is being used in 'stand
// alone' interactive mode.
// However, when called remotely the function is only called once with
// normalise_ff set to 1 and it is assumed that the remote client will be
// 'forced' to set a mask or have a full mask generated before calling this
// function.
{
 int lht,lwd,imfmt,idx,rgbpos,width_stride,rawdou;
 double mr,mg,mb,meanr,meang,meanb,dtmp;
 size_t imsz,rgbimsz,stdx;
 char msgtxt[MSGTXT_LEN];
 unsigned char *tmploc,cref[1024];    
 int16_t bitcount;
 
 imfmt=0; 
 rawdou=0; // Is the FF image raw doubles format?
 
 // Read the image file header to get dimensions and file type
 if(!get_pgm_header(Selected_FF_filename, &lht,&lwd))     imfmt=SAF_YP5; //pgm
 else if(!get_ppm_header(Selected_FF_filename, &lht,&lwd))imfmt=SAF_RGB; //ppm
 else if(!get_bmp_header(Selected_FF_filename, &lht,&lwd,&bitcount)){    //bmp
    switch(bitcount){
        case 8: imfmt = SAF_BM8; break;                       // greyscale bmp
        case 24:imfmt = SAF_BMP; break;                       // colour    bmp  
        default:
             show_message("Selected flat field bmp image is not 8 or 24 bit"
                       " (other bit depths are not supported). Cannot proceed.",
                                                         "FAILED: ", MT_ERR, 1);
        nullify_flatfield(); return 1;
      }   
 } else { // It is not one of the allowed unsigned char formats so see if
          // it is a raw doubles flat field image:
         
    // Read the external qih file header to get dimensions and file type
    if(read_qih_file(Selected_FF_filename,&lht,&lwd, &imfmt)){
       show_message("Selected flat field image(s) is not of an acceptable"
       " format. No flat field correction can be done. Try selecting another"
                                              " file.","FAILED: ",MT_ERR,1);
       nullify_flatfield(); return 1;
      }
    rawdou=1; // Header checks out OK so flag this as a raw doubles FF
  }  


 // Check dimensions are identical to current main image
 if(lht!=Selected_Ht){
    show_message("Selected flat field image is not the same height as main"
                             " image. Cannot proceed.","FAILED: ",MT_ERR,1);
    nullify_flatfield(); return 1;
   }     
 if(lwd!=Selected_Wd){
    show_message("Selected flat field image is not the same width as main"
                             " image. Cannot proceed.","FAILED: ",MT_ERR,1);
    nullify_flatfield(); return 1;
   }     

 // OK, now see if we can allocate memory for the flat field image
 if(rawdou==0){
     
  switch(imfmt){
    case SAF_YP5:
    case SAF_BM8:
     width_stride=Selected_Wd;
    break;
    case SAF_RGB:
    case SAF_BMP:
     width_stride=Selected_Wd*3;
    break;
    default: // This should not happen
        show_message("Unrecognised u.char image format for flat field image.",
                                                "Program Error: ",MT_ERR,1);
        nullify_flatfield();
        return 1;
    }
    
 } else {
     
  switch(imfmt){
    case FFIMG_Y:
     width_stride=Selected_Wd;
    break;
    case FFIMG_RGB:
     width_stride=Selected_Wd*3;
    break;
    default: // This should not happen
        show_message("Unrecognised doubles image format for flat field image.",
                                                "Program Error: ",MT_ERR,1);
        nullify_flatfield();
        return 1;
    }
  } 
  
 imsz=(size_t)Selected_Ht*(size_t)width_stride; 
 rgbimsz=imsz;
 
if(rawdou==0){
     
 tmploc=calloc(rgbimsz,sizeof(unsigned char));
 if(tmploc==NULL){
     show_message("Failed to allocate memory to store flat field image. Cannot"
                                " proceed to load it.","FAILED: ",MT_ERR,1);
     nullify_flatfield(); return 1;
    }
        
 // We got memory, so now try reading the image into it
 snprintf(msgtxt,sizeof(msgtxt),"There was a problem reading the chosen flat field file (u.char). Cannot proceed.");
 switch(imfmt){
        case SAF_YP5: 
            if(get_pgm(Selected_FF_filename, &tmploc, &lht,&lwd)){
              show_message(msgtxt,"FAILED: ",MT_ERR,1);
              nullify_flatfield(); free(tmploc); return 1;
            }
        break;
        case SAF_BM8: 
            if(get_bmp(Selected_FF_filename, &tmploc, &lht, &lwd, cref)){
              show_message(msgtxt,"FAILED: ",MT_ERR,1);
              nullify_flatfield(); free(tmploc); return 1;
            }
        break;
        case SAF_RGB:
            if(get_ppm(Selected_FF_filename, &tmploc)){
              show_message(msgtxt,"FAILED: ",MT_ERR,1);
              nullify_flatfield(); free(tmploc); return 1;
            }
        break;
        case SAF_BMP:
            if(get_bmp(Selected_FF_filename, &tmploc, &lht, &lwd, cref)){
              show_message(msgtxt,"FAILED: ",MT_ERR,1);
              nullify_flatfield(); free(tmploc); return 1;
            }
        break;
        default: // This should not happen
         show_message("Unrecognised image format for flat field image.",
                                                "Program Error: ",MT_ERR,1);
         nullify_flatfield(); free(tmploc); return 1;
    }
    
  // The image is now loaded into an unsigned char array but corrections
  // are done in doubles. So make a raw doubles array and copy over the
  // values:
  if(resize_memblk((void **)&FF_Image,rgbimsz,sizeof(double),
                                              "the flat field image (doubles)"))
   {
    nullify_flatfield();
    free(tmploc);
    return 1;
   }
  for(stdx=0;stdx<rgbimsz;stdx++) FF_Image[stdx]=(double)tmploc[stdx];
  // Now we are done with tmploc. Also we need to change flags to the
  // raw doubles version for the rest of this function. So ...
  free(tmploc);
  rawdou=1;
  switch(imfmt){
        case SAF_YP5: 
        case SAF_BM8: 
            imfmt=DFIMG_Y;
        break;
        default:
            imfmt=DFIMG_RGB;
        break;
    }  
    
 } else { // If the user wants to load a raw doubles flat field ...
     
 if(resize_memblk((void **)&FF_Image,rgbimsz,sizeof(double), "the flat field image (doubles)"))
  {
   nullify_flatfield();
   return 1;
  }

 // We got memory, so now try reading the image into it
 snprintf(msgtxt,sizeof(msgtxt),"There was a problem reading the chosen flat field file. Cannot proceed.");
 if(read_raw_doubles(Selected_FF_filename, &FF_Image,lht,lwd,imfmt)){
    show_message(msgtxt,"FAILED: ",MT_ERR,1);
    nullify_flatfield(); return 1;
   }
     
 }
  
 if(normalise_ff){

 // If we have got to here then the flat field correction image is
 // loaded as an array of raw doubles in FF_Image, the rawdou flag is
 // set to 1 and the imfmt flag is set to DFIMG_Y or DFIMG_RGB.
  
 // Test if image can be used for flat field correction and set the
 // fffile_loaded flag appropriately. All testing and normalising is
 // done within the confines of the support mask. This function could
 // not have been called unless an updated support mask was already
 // and successfully generated (either from a user-supplied file or
 // an internally generated full-support mask) so it is safe to use
 // MaskIm[] to the current image size indices.
 
 // Prior to this point imsz and rgbimsz were set equal to each other.
 // Now we will be using the mask which is only Selected_Ht*Selected_Wd
 // and not 3 times that size, even if we have loaded a colour flat
 // field file. So we must set imsz to only a single frame size and use
 // that as the primary index for loops otherwise we will overshoot the
 // mask array and get a segmentation fault:
 imsz=(size_t)Selected_Ht*(size_t)Selected_Wd; 

 
 switch(imfmt){
    case DFIMG_Y: // Greyscale formats (i.e. single channel)
    
         // Test for maximum pixel value. No realistic flat field
         // correction image taken with a camera down a microscope
         // should have a maximum pixel value of <1 assuming grey level
         // readout is on an integer scale starting at 0.
         mr=-1.0; meanr=0;
         for(idx=0;idx<imsz;idx++){
             if(MaskIm[idx]>0){
               dtmp=FF_Image[idx];
               if(dtmp>mr) mr=dtmp;
               meanr+=dtmp; // Accumulator to calc. the mean.
              }
            }
         if(mr<0.5){
           show_message("Flat field image is loadable but not useable for flat"
                        " field correction (no pixel is greater than 0).",
                                                       "FAILED: ",MT_ERR,1);
           nullify_flatfield(); return 1;
         }
         // Now normalise by dividing all pixel values by the mean
         meanr/=Mask_supp_size; // Mean value
         snprintf(msgtxt,sizeof(msgtxt),"Flat field image mean Y = %g",meanr);
         show_message(msgtxt,"FYI: ",MT_INFO,0);
         for(idx=0;idx<imsz;idx++){
             if(MaskIm[idx]>0){
                  FF_Image[idx]/=meanr;
              }}
         // Mark the master flat field as being successfully loaded
         fffile_loaded=FFIMG_Y;
        break;
    case DFIMG_RGB: // Colour formats
         mr=-1.0;mg=-1.0;mb=-1.0;meanr=0.0;meang=0.0;meanb=0.0;
         for(idx=0,rgbpos=0;idx<imsz;idx++){
             if(MaskIm[idx]>0){
               dtmp=FF_Image[rgbpos];
               if(dtmp>mr) mr=dtmp;
               meanr+=dtmp; // Accumulator to calc. the mean R value.
               rgbpos++;
               dtmp=FF_Image[rgbpos];
               if(dtmp>mg) mg=dtmp;
               meang+=dtmp; // Accumulator to calc. the mean G value.
               rgbpos++;
               dtmp=FF_Image[rgbpos];
               if(dtmp>mb) mb=dtmp;
               meanb+=dtmp; // Accumulator to calc. the mean B value.
               rgbpos++;
             } else rgbpos+=3;
           }
         if(mr<0.5){
           show_message("Flat field image is loadable but not useable for flat"
                        " field correction (no red pixel is greater than 0).",
                                                       "FAILED: ",MT_ERR,1);
           nullify_flatfield(); return 1;
         }
         if(mg<0.5){
           show_message("Flat field image is loadable but not useable for flat"
                        " field correction (no green pixel is greater than 0).",
                                                       "FAILED: ",MT_ERR,1);
           nullify_flatfield(); return 1;
         }
         if(mb<0.5){
           show_message("Flat field image is loadable but not useable for flat"
                        " field correction (no blue pixel is greater than 0).",
                                                       "FAILED: ",MT_ERR,1);
           nullify_flatfield(); return 1;
         }
         
         // Now normalise by dividing all pixel values by the mean
         meanr/=Mask_supp_size; // Mean value
         meang/=Mask_supp_size; // Mean value
         meanb/=Mask_supp_size; // Mean value
         snprintf(msgtxt,sizeof(msgtxt),"Flat field image mean RGB = %g, %g, %g",
                                                             meanr,meang,meanb);
         show_message(msgtxt,"FYI: ",MT_INFO,0);
         
         for(idx=0,rgbpos=0;idx<imsz;idx++){
             if(MaskIm[idx]>0){
               FF_Image[rgbpos++]/=meanr;
               FF_Image[rgbpos++]/=meang;
               FF_Image[rgbpos++]/=meanb;
              } else rgbpos+=3;
            }
         
         // Mark the master flat field as being successfully loaded  
         fffile_loaded=FFIMG_RGB;
        break;
        default: // This should not happen
         show_message("Unrecognised image format for flat field image.",
                                                "Program Error: ",MT_ERR,1);
         nullify_flatfield(); return 1;
    }

 } else fffile_loaded=FFIMG_NORM; // This indicates that a flat field
                                  // image was loaded successfully but
                                  // is yet to be normalised.

 // OK. Image is loaded correctly and is useable. Now we set the
 // associated global variables and GUI labels, etc.
 FFht=lht; FFwd=lwd;
 sprintf(FFFile,"%s",Selected_FF_filename);
 snprintf(msgtxt,sizeof(msgtxt),"Flat field correction image loaded: %s",FFFile);
 show_message(msgtxt,"FYI: ",MT_INFO,0);
 // fffile_loaded was set in the above switch block.
 if(gtk_widget_is_visible(Win_cam_settings)==TRUE){
     // Set label to show filename and other GUI controls/labels:
     gtk_label_set_text(GTK_LABEL(CamsetWidget[windex_rffi]),
                                                        name_from_path(FFFile));  
     gtk_widget_set_sensitive (chk_useffcor,TRUE);
     gtk_widget_set_sensitive (CamsetWidget[windex_uf],TRUE);
     gtk_widget_set_sensitive (CamsetWidget[windex_uf2],TRUE);
  }
 
 return 0;
}

int test_selected_pcd_filename(char *filename)
// Attempt to read the file header and see if it is suitable for use as a
// preview colour dark field subtraction image. If successful, copy the file
// name into the global Selected_PCD_filename and set the PrevCD_Pending flag to
// 1 and sets the GUI widgets to sensitive (it sets them insensitive otherwise) 
// Return 0 on success and sets PrevCD_Pending to 1.
// It returns 1 on failure.
{
 char msgtxt[4202];
 int lht,lwd,imfmt;
 int16_t bitcount;

 // The default position - we'll update it if filename passes the test 
  PrevCD_Pending=0;

 // No useable mask selected
 if(!strcmp(filename,"[None]") || !strcmp(filename,"[Full]") ||
    !strcmp(filename,"[UNDF]") || !strcmp(filename,"None.bmp")){
   if(!strcmp(filename,"None.bmp")) sprintf(Selected_PCD_filename,"[None]");
   gtk_check_button_set_active(GTK_CHECK_BUTTON(chk_usepcd),FALSE);
   if(GTK_IS_WIDGET (chk_usepcd))gtk_widget_set_sensitive (chk_usepcd,FALSE);
   if(GTK_IS_WIDGET (CamsetWidget[windex_upc]))
                      gtk_widget_set_sensitive (CamsetWidget[windex_upc],FALSE);
   if(GTK_IS_WIDGET (CamsetWidget[windex_upc2]))
                     gtk_widget_set_sensitive (CamsetWidget[windex_upc2],FALSE);
   return 1;
 }

 // Read the image file header to get dimensions and file type
 imfmt=SAF_YUYV; // I use SAF_YUYV just as a reference value to see if
                 // it changes (if it doesn't then no acceptable format
                 // was found).
 if(!get_ppm_header(filename, &lht,&lwd))imfmt=SAF_RGB;       // PPM colour
 else if(!get_bmp_header(filename, &lht,&lwd,&bitcount)){     // BMP
    switch(bitcount){
        case 24:imfmt=SAF_BMP; break;  // colour bmp  
        default:
             show_message("Selected preview colour dark bmp image is not 24 bit"
                       " (other bit depths are not supported). Cannot proceed.",
                                                       "FAILED: ",MT_ERR,1);
             return 1;
      }   
 }

 if(imfmt==SAF_YUYV) { // It is not one of the allowed unsigned char formats
         show_message("Selected preview colour dark image is not of an"
                      " acceptable format. Preview colour dark field correction"
                      " can't be done. Try selecting another file.","FAILED: ",
                                                                  MT_ERR,1);
         return 1;
        }                 

    sprintf(Selected_PCD_filename,"%s",filename);
    PrevCD_Pending=1;
    if(GTK_IS_WIDGET (chk_usepcd))gtk_widget_set_sensitive (chk_usepcd,TRUE);
    if(GTK_IS_WIDGET (CamsetWidget[windex_upc]))
                       gtk_widget_set_sensitive (CamsetWidget[windex_upc],TRUE);
    if(GTK_IS_WIDGET (CamsetWidget[windex_upc2]))
                      gtk_widget_set_sensitive (CamsetWidget[windex_upc2],TRUE);

    snprintf(msgtxt,sizeof(msgtxt),"You selected preview colour dark image: %s\nWill attempt to"
                   " load and process it when you click 'Apply'.",
                                         name_from_path(Selected_PCD_filename));
    show_message(msgtxt,"FYI: ",MT_INFO,1);

   return 0;
}

