void nullify_pcd(void)
// Nullify the preview colour dark field image (set it to all zeros)
{
 // Re-initialise the preview mask to be all 255 across the whole field 
 memset(Preview_ColDark, 0, PreviewImg_rgb_size*sizeof(unsigned char));
 PrevCD_Loaded = MASK_NONE;
 PrevCD_Perform = 0;

 // GUI stuff - don't do this if the camera settings window is not
 // visible because the dynamically allocated GUI controls will not be
 // addressable and GTK errors will result. This situation may arise
 // during the running of a script if the camera settings window was
 // closed prior to running it.
 sprintf(PCDFile,"[None]");
 if(gtk_widget_is_visible(Win_cam_settings)==TRUE){
    gtk_check_button_set_active(GTK_CHECK_BUTTON(chk_usepcd),FALSE);
    gtk_widget_set_sensitive (chk_usepcd,FALSE);
    gtk_label_set_text(GTK_LABEL(CamsetWidget[windex_upc]),"No");
    gtk_widget_set_sensitive (CamsetWidget[windex_upc],FALSE);
    gtk_widget_set_sensitive (CamsetWidget[windex_upc2],FALSE);
    // Set label to show nullified ('[Full]') filename
    gtk_label_set_text(GTK_LABEL(CamsetWidget[windex_pcdi]), PCDFile);  
   }
 if(PrevCD_Pending) show_message("Any pre-existing Preview colour dark image has been nullified. Preview colour dark fielding is disabled till a new image is loaded.","FYI: ",MT_INFO,1);
 return;
}

void set_pcd_pending(void)
{
 if(!strcmp(Selected_PCD_filename,"[None]") || !strcmp(Selected_PCD_filename,"[Full]") || !strcmp(Selected_PCD_filename,"[UNDF]")){
   PrevCD_Pending=0;
 } else PrevCD_Pending=1;
}

static int init_pcd_image(void)
// Load any user-specified preview colour dark file and get it ready for use.
// Check the format and support, etc.
// Return 0 on success and the loaded image is present in Preview_ColDark.
// Return 1 on failure and Preview_ColDark is set to all zeros.
{
 int lht,lwd,imfmt,idx;
 unsigned char *tmploc;
 int tmpimsz;
 char msgtxt[MSGTXT_LEN];
 unsigned char cref[1024];    
 int16_t bitcount;

 if(!strcmp(Selected_PCD_filename,"[None]") ||
    !strcmp(Selected_PCD_filename,"[Full]") ||
    !strcmp(Selected_PCD_filename,"[UNDF]")){
    PrevCD_Pending=0;
    if(gtk_widget_is_visible(Win_cam_settings)==TRUE){
      gtk_check_button_set_active(GTK_CHECK_BUTTON(chk_usepcd),FALSE);
      gtk_widget_set_sensitive (chk_usepcd,FALSE);
      gtk_widget_set_sensitive (CamsetWidget[windex_upc],FALSE);
      gtk_widget_set_sensitive (CamsetWidget[windex_upc2],FALSE);
     }
    return 0;
  }

 // Read the image file header to get dimensions and file type.
 // The errors shouldn't occur because we checked previously but I keep the
 // checks for them in because when this is part of the full PARDUS server the
 // file names will be supplied over the network from the client script and not
 // via popup file dialog boxes (as they are here in this standalone version
 // and where the previous checks were done).
 if(!get_ppm_header(Selected_PCD_filename, &lht,&lwd))imfmt=SAF_RGB;   // PPM
 else if(!get_bmp_header(Selected_PCD_filename, &lht,&lwd,&bitcount)){ // BMP
    switch(bitcount){
      case 24:imfmt=SAF_BMP; break;     // colour    bmp  
      default:
        show_message("Selected preview mask bmp image is not 24 bit (other bit"
             " depths are not supported). Cannot proceed.","FAILED: ",MT_ERR,1);
        nullify_pcd(); return 1;
      }   
 } else { // It is not one of the allowed unsigned char formats
      show_message("Selected preview colour dark image is not of an acceptable"
                   " format. No preciew colour dark correction can be done."
                   " Try selecting another file.","FAILED: ",MT_ERR,1);
      nullify_pcd(); return 1;
 }

 tmpimsz=PreviewImg_rgb_size;

 // Check dimensions are identical to current main image
 if(lht!=PreviewHt){
    show_message("Selected preview colour dark image is not the same height as"
                     " the preview image. Cannot proceed.","FAILED: ",MT_ERR,1);
    nullify_pcd(); return 1;
   }     
 if(lwd!=PreviewWd){
    show_message("Selected preview colour dark image is not the same width as"
                     " the preview image. Cannot proceed.","FAILED: ",MT_ERR,1);
    nullify_pcd(); return 1;
   }     

 // We got memory for the colour dark image. Now get memory for a temporary
 // array to load the selected image and try reading the image into it
 tmploc=calloc(tmpimsz,sizeof(unsigned char));
 if(tmploc==NULL){
     show_message("Failed to allocate memory to store the preview colour dark"
                      " image. Cannot proceed to load it.","FAILED: ",MT_ERR,1);
     nullify_pcd(); return 1;
    }

 // We got memory, so now try reading the image into it
 snprintf(msgtxt,sizeof(msgtxt),"There was a problem reading the chosen preview colour dark"
                                                " image file. Cannot proceed.");
 switch(imfmt){
    case SAF_RGB:
        if(get_ppm(Selected_PCD_filename, &tmploc)){
          show_message(msgtxt,"FAILED: ",MT_ERR,1);
          nullify_pcd(); free(tmploc); return 1;
        }
    break;
    case SAF_BMP:
        if(get_bmp(Selected_PCD_filename, &tmploc, &lht, &lwd, cref)){
          show_message(msgtxt,"FAILED: ",MT_ERR,1);
          nullify_pcd(); free(tmploc); return 1;
        }
    break;
    default: // This should not happen
    show_message("Unrecognised image format for the preview colour dark image.",
                                                    "Program Error: ",MT_ERR,1);
    nullify_pcd(); free(tmploc); return 1;
  }

 // Now copy the read image into Preview_ColDark.

 for(idx=0;idx<PreviewImg_rgb_size;idx++){
     Preview_ColDark[idx]=tmploc[idx];
   }
 PrevCD_Loaded = MASK_YRGB;

 // we're done with the temporary array now so free it
 free(tmploc);

 // Now we set the GUI:
 sprintf(PCDFile,"%s",Selected_PCD_filename);
 snprintf(msgtxt,sizeof(msgtxt),"Preview colour dark image loaded: %s",PCDFile);
 show_message(msgtxt,"FYI: ",MT_INFO,0);
 
 if(gtk_widget_is_visible(Win_cam_settings)==TRUE){
     //set label to show filename
     gtk_label_set_text(GTK_LABEL(CamsetWidget[windex_pcdi]),
                                                       name_from_path(PCDFile));  
     gtk_widget_set_sensitive (chk_usepcd,TRUE);
     gtk_widget_set_sensitive (CamsetWidget[windex_upc],TRUE);
     gtk_widget_set_sensitive (CamsetWidget[windex_upc2],TRUE);

  }
 
 return 0;
}

int test_selected_pmsk_filename(char *filename)
// Attempt to read the file header and see if it is suitable for use as a
// preview mask. If successful, copy the file name into the PrevStat
// Selected_Mask_filename variable and set the PrevStat.mask_pending flag to 1
// and sets the GUI widgets to sensitive (it sets them insensitive otherwise) 
// Return 0 on success and sets PrevStat.mask_pending to 1.
// It returns 1 on failure.
{
 char msgtxt[4202];
 int lht,lwd,imfmt;
 int16_t bitcount;

  // The default position - we'll update it if filename passes the test.
  PrevStat.mask_pending=0;
 
 // No useable mask selected
 if(!strcmp(filename,"[None]") || !strcmp(filename,"[Full]") ||
    !strcmp(filename,"[UNDF]") || !strcmp(filename,"None.bmp")){
   if(!strcmp(filename,"None.bmp"))
     sprintf(PrevStat.Selected_Mask_filename,"[None]");
   if(gtk_widget_is_visible(Win_cam_settings)==TRUE){
     gtk_check_button_set_active(GTK_CHECK_BUTTON(chk_usepmsk),FALSE);
     gtk_check_button_set_active(GTK_CHECK_BUTTON(chk_dsppmsk),FALSE);
     gtk_widget_set_sensitive (chk_usepmsk,FALSE);
     gtk_widget_set_sensitive (chk_dsppmsk,FALSE);
     gtk_widget_set_sensitive (CamsetWidget[windex_upm],FALSE);
     gtk_widget_set_sensitive (CamsetWidget[windex_upm2],FALSE);
     gtk_widget_set_sensitive (CamsetWidget[windex_dpm],FALSE);
     gtk_widget_set_sensitive (CamsetWidget[windex_dpm2],FALSE);
    }
   return 1;
 }


 // Read the mask image file header to get dimensions and file type
 imfmt=SAF_YUYV; // I use SAF_YUYV just as a reference value to see if it
                 // changes (if it doesn't then no acceptable format was found).
 if(!get_pgm_header(filename, &lht,&lwd))     imfmt=SAF_YP5;  // PGM greyscale 
 else if(!get_ppm_header(filename, &lht,&lwd))imfmt=SAF_RGB;  // PPM colour
 else if(!get_bmp_header(filename, &lht,&lwd,&bitcount)){     // BMP
    switch(bitcount){
        case 8: imfmt=SAF_BM8; break;     // greyscale bmp
        case 24:imfmt=SAF_BMP; break;     // colour    bmp  
        default:
             show_message("Selected preview mask bmp image is not 8 or 24 bit"
                       " (other bit depths are not supported). Cannot proceed.",
                                                       "FAILED: ",MT_ERR,1);
             return 1;
      }   
 } 
 if(imfmt==SAF_YUYV) { // It is not one of the allowed unsigned char formats
         show_message("Selected preview mask image is not of an acceptable"
          " format. No custom masking can be done. Try selecting another file.",
                                                       "FAILED: ",MT_ERR,1);
         return 1;
        }                 

    sprintf(PrevStat.Selected_Mask_filename,"%s",filename);
    PrevStat.mask_pending=1;
    if(gtk_widget_is_visible(Win_cam_settings)==TRUE){
       gtk_widget_set_sensitive (chk_usepmsk,TRUE);
       gtk_widget_set_sensitive (chk_dsppmsk,TRUE);
       gtk_widget_set_sensitive (CamsetWidget[windex_upm],TRUE);
       gtk_widget_set_sensitive (CamsetWidget[windex_upm2],TRUE);
       gtk_widget_set_sensitive (CamsetWidget[windex_dpm],TRUE);
       gtk_widget_set_sensitive (CamsetWidget[windex_dpm2],TRUE);
      }

    snprintf(msgtxt,sizeof(msgtxt),"You selected preview mask image: %s\nWill attempt to load"
                   " and process it when you click 'Apply'.",
                               name_from_path(PrevStat.Selected_Mask_filename));
    show_message(msgtxt,"FYI: ",MT_INFO,1);
   return 0;
}

