{
 if(!strcmp(PrevStat.Selected_Mask_filename,"[None]") || !strcmp(PrevStat.Selected_Mask_filename,"[Full]") || !strcmp(PrevStat.Selected_Mask_filename,"[UNDF]")){
   PrevStat.mask_pending=0;
 } else PrevStat.mask_pending=1;
}

static int init_pmask_image(void)
// Load any user-specified preview mask file and get it ready for use. Check the
// format and support, etc.
// Return 0 on success and the loaded mask is present in PrevStat.MaskIm.
// Return 1 on failure and PrevStat.MaskIm is set to full support.
{
 int lht,lwd,imfmt,idx,rgbpos;
 unsigned char *tmploc;
 double d1,d2,d3;
 int msupp;
 int tmpimsz;
 char msgtxt[MSGTXT_LEN];
 unsigned char cref[1024];    
 int16_t bitcount;

 if(!strcmp(PrevStat.Selected_Mask_filename,"[None]") || !strcmp(PrevStat.Selected_Mask_filename,"[Full]") || !strcmp(PrevStat.Selected_Mask_filename,"[UNDF]")){
   PrevStat.mask_pending=0;
   if(gtk_widget_is_visible(Win_cam_settings)==TRUE){
     gtk_check_button_set_active(GTK_CHECK_BUTTON(chk_usepmsk),FALSE);
     gtk_check_button_set_active(GTK_CHECK_BUTTON(chk_dsppmsk),FALSE);
     gtk_widget_set_sensitive (chk_usepmsk,FALSE);
     gtk_widget_set_sensitive (chk_dsppmsk,FALSE);
     gtk_widget_set_sensitive (CamsetWidget[windex_upm],FALSE);
     gtk_widget_set_sensitive (CamsetWidget[windex_upm2],FALSE);
     gtk_widget_set_sensitive (CamsetWidget[windex_dpm],FALSE);
     gtk_widget_set_sensitive (CamsetWidget[windex_dpm2],FALSE);
    }
   return 0;
 }

 // Read the mask image file header to get dimensions and file type.
 // The errors shouldn't occur because we checked previously but I keep the
 // checks for them in because when this is part of the full PARDUS server the
 // file names will be supplied over the network from the client script and not
 // via popup file dialog boxes (as they are here in this standalone version
 // and where the previous checks were done).
 if(!get_pgm_header(PrevStat.Selected_Mask_filename, &lht,&lwd))     imfmt=SAF_YP5;  // PGM greyscale 
 else if(!get_ppm_header(PrevStat.Selected_Mask_filename, &lht,&lwd))imfmt=SAF_RGB;  // PPM colour
 else if(!get_bmp_header(PrevStat.Selected_Mask_filename, &lht,&lwd,&bitcount)){     // BMP
    switch(bitcount){
        case 8: imfmt=SAF_BM8; break;     // greyscale bmp
        case 24:imfmt=SAF_BMP; break;     // colour    bmp  
        default:
             show_message("Selected preview mask bmp image is not 8 or 24 bit (other bit depths are not supported). Cannot proceed.","FAILED: ",MT_ERR,1);
             nullify_pmask(); return 1;
      }   
 } else { // It is not one of the allowed unsigned char formats
         show_message("Selected preview mask image is not of an acceptable format. No custom masking can be done. Try selecting another file.","FAILED: ",MT_ERR,1);
         nullify_pmask(); return 1;
        }

  switch(imfmt){
    case SAF_YP5:
    case SAF_BM8:
     tmpimsz=PreviewImg_size;
    break;
    case SAF_RGB:
    case SAF_BMP:
     tmpimsz=PreviewImg_rgb_size;
    break;
    default: // This should not happen
        show_message("Unrecognised image format for preview mask image.","Program Error: ",MT_ERR,1);
        nullify_pmask();
        return 1;
    }

 // Check dimensions are identical to current main image
 if(lht!=PreviewHt){
    show_message("Selected preview mask image is not the same height as the preview image. Cannot proceed.","FAILED: ",MT_ERR,1);
    nullify_pmask(); return 1;
   }     
 if(lwd!=PreviewWd){
    show_message("Selected preview mask image is not the same width as the preview image. Cannot proceed.","FAILED: ",MT_ERR,1);
    nullify_pmask(); return 1;
   }     

 // We got memory for the mask. Now get memory for a temporary array to
 // load the mask image and try reading the image into it
 tmploc=calloc(tmpimsz,sizeof(unsigned char));
 if(tmploc==NULL){
     show_message("Failed to allocate memory to store the preview mask image. Cannot proceed to load it.","FAILED: ",MT_ERR,1);
     nullify_pmask(); return 1;
    }

 // We got memory, so now try reading the image into it
 snprintf(msgtxt,sizeof(msgtxt),"There was a problem reading the chosen preview mask file. Cannot proceed.");
 switch(imfmt){
        case SAF_YP5: 
            if(get_pgm(PrevStat.Selected_Mask_filename, &tmploc, &lht,&lwd)){
              show_message(msgtxt,"FAILED: ",MT_ERR,1);
              nullify_pmask(); free(tmploc); return 1;
            }
        break;
        case SAF_BM8: 
            if(get_bmp(PrevStat.Selected_Mask_filename, &tmploc, &lht, &lwd, cref)){
              show_message(msgtxt,"FAILED: ",MT_ERR,1);
              nullify_pmask(); free(tmploc); return 1;
            }
        break;
        case SAF_RGB:
            if(get_ppm(PrevStat.Selected_Mask_filename, &tmploc)){
              show_message(msgtxt,"FAILED: ",MT_ERR,1);
              nullify_pmask(); free(tmploc); return 1;
            }
        break;
        case SAF_BMP:
            if(get_bmp(PrevStat.Selected_Mask_filename, &tmploc, &lht, &lwd, cref)){
              show_message(msgtxt,"FAILED: ",MT_ERR,1);
              nullify_pmask(); free(tmploc); return 1;
            }
        break;
        default: // This should not happen
         show_message("Unrecognised image format for the preview mask image.","Program Error: ",MT_ERR,1);
         nullify_pmask(); free(tmploc); return 1;
    }

 // Now convert the mask image into a binary unsigned char array
 // whatever the original file format was by thresholding at a pixel
 // value of 127.
 msupp=0;
 switch(imfmt){
    case SAF_YP5:
    case SAF_BM8:
      for(idx=0;idx<PreviewImg_size;idx++){
         if(tmploc[idx]>127){ PrevStat.MaskIm[idx]=255; msupp++;}
         else PrevStat.MaskIm[idx]=0;
       }
    break;
    case SAF_RGB:
    case SAF_BMP:
     for(idx=0,rgbpos=0;idx<PreviewImg_size;idx++){
         d1=(double)tmploc[rgbpos++];
         d2=(double)tmploc[rgbpos++];
         d3=(double)tmploc[rgbpos++];
         d1=(d1+d2+d3)/3.0; // Intensity from RGB        
         if(d1>127.0){ PrevStat.MaskIm[idx]=255; msupp++;}
         else PrevStat.MaskIm[idx]=0;
       }
    break;
    default: // This can't happen - we checked above
    break;
  }

 // we're done with the temporary array now so free it
 free(tmploc);

 // Check that the mask has at least 1 pixel that is non-zero:
 if(msupp==0){
   show_message("Chosen preview mask has no support so cannot be used.","FAILED: ",MT_ERR,1);
   nullify_pmask(); return 1;
  }

 // Now we set the PrevStat structure variable values and GUI:
 PrevStat.Mask_supp_size=(double)msupp;
 sprintf(PrevStat.MaskFile,"%s",PrevStat.Selected_Mask_filename);
 snprintf(msgtxt,sizeof(msgtxt),"Preview mask image loaded: %s",PrevStat.MaskFile);
 show_message(msgtxt,"FYI: ",MT_INFO,0);
 PrevStat.mskfile_loaded=MASK_YRGB;
 
 if(gtk_widget_is_visible(Win_cam_settings)==TRUE){
     //set label to show filename
     gtk_label_set_text(GTK_LABEL(CamsetWidget[windex_pmski]), name_from_path(PrevStat.MaskFile));  
     gtk_widget_set_sensitive (chk_usepmsk,TRUE);
     gtk_widget_set_sensitive (chk_dsppmsk,TRUE);
     gtk_widget_set_sensitive (CamsetWidget[windex_upm],TRUE);
     gtk_widget_set_sensitive (CamsetWidget[windex_upm2],TRUE);
     gtk_widget_set_sensitive (CamsetWidget[windex_dpm],TRUE);
     gtk_widget_set_sensitive (CamsetWidget[windex_dpm2],TRUE);
  }
 
 return 0;
}

int test_selected_msk_filename(char *filename)
// Attempt to read the file header and see if it is suitable for use as
// a corrections mask. If successful, copy the file name into the global
// Selected_Mask_filename variable and set the mask_pending flag and GUI
// widgets accordingly. 
// Return 0 on success, 1 on failure.
{
 char msgtxt[4202];
 int lht,lwd,imfmt;
 int16_t bitcount;
 
 // No useable mask selected
 if(!strcmp(filename,"[None]") || !strcmp(filename,"[Full]") ||
    !strcmp(filename,"[UNDF]") || !strcmp(filename,"None.bmp")){
   mask_pending=0;
   if(!strcmp(filename,"None.bmp")) sprintf(PrevStat.Selected_Mask_filename,"[None]");
   if(gtk_widget_is_visible(Win_cam_settings)==TRUE){
     gtk_check_button_set_active(GTK_CHECK_BUTTON(chk_usemskcor),FALSE);
     gtk_widget_set_sensitive (chk_usemskcor,FALSE);
     gtk_widget_set_sensitive (CamsetWidget[windex_um],FALSE);
     gtk_widget_set_sensitive (CamsetWidget[windex_um2],FALSE);
    }
   return 1;
 }


 // Read the mask image file header to get dimensions and file type
 imfmt=SAF_YUYV; // I use SAF_YUYV just as a reference value to see if it
                 // changes (if it doesn't then no acceptable format was found).
 if(!get_pgm_header(filename, &lht,&lwd))     imfmt=SAF_YP5;  // PGM greyscale 
 else if(!get_ppm_header(filename, &lht,&lwd))imfmt=SAF_RGB;  // PPM colour
 else if(!get_bmp_header(filename, &lht,&lwd,&bitcount)){     // BMP
    switch(bitcount){
        case 8: imfmt=SAF_BM8; break;     // greyscale bmp
        case 24:imfmt=SAF_BMP; break;     // colour    bmp  
        default:
             show_message("Selected mask bmp image is not 8 or 24 bit (other"
                          " bit depths are not supported). Cannot proceed.",
                                                       "FAILED: ",MT_ERR,1);
             return 1;
      }   
 } 
 if(imfmt==SAF_YUYV) { // It is not one of the allowed unsigned char formats
         show_message("Selected mask image is not of an acceptable format. No"
                     " custom masking can be done. Try selecting another file.",
                                                       "FAILED: ",MT_ERR,1);
         return 1;
        }                 

    sprintf(PrevStat.Selected_Mask_filename,"%s",filename);
    mask_pending=1;
    if(gtk_widget_is_visible(Win_cam_settings)==TRUE){
      gtk_widget_set_sensitive (chk_usemskcor,TRUE);
      gtk_widget_set_sensitive (CamsetWidget[windex_um],TRUE);
      gtk_widget_set_sensitive (CamsetWidget[windex_um2],TRUE);
     }

    snprintf(msgtxt,sizeof(msgtxt),"You selected mask image: %s\nWill attempt to load and"
                   " process it when you click 'Apply'.",
                                        name_from_path(PrevStat.Selected_Mask_filename));
    show_message(msgtxt,"FYI: ",MT_INFO,1);
   return 0;
}

static void btn_cs_load_mask_click(GtkWidget *widget, gpointer data) 
// This just gets the file name and checks the format - it doesn't load
// the image. Acceptable input images can only be of 8 bpp or 24 bpp BMP, binary
// pgm or ppm formats. The actual mask used in the program will be binary 8 bpp
// so if a colour image is supplied this will later be processed down to 24 bpp
// binary by thresholding the intensity value derived from the RGB components
// about a value of 127.
{
 GtkFileDialog *file_dialog;
 GListStore *filters;
 GtkFileFilter *pgm_filter;
 GtkFileFilter *ppm_filter;
 GtkFileFilter *bmp_filter;

 mask_pending=0;
 
 // Set up the 'file load' dialogue with the corrections mask choices
  // Create a GListStore to hold the filters
  filters = g_list_store_new (GTK_TYPE_FILE_FILTER);

  // Create the .pgm filter
  pgm_filter = gtk_file_filter_new ();
  gtk_file_filter_add_pattern (pgm_filter, "*.pgm");
  gtk_file_filter_set_name (pgm_filter, "pgm images");
  g_list_store_append (filters, pgm_filter); // Add to the list store
  g_object_unref(pgm_filter); // GListStore takes a reference

  // Create the .ppm filter
  ppm_filter = gtk_file_filter_new ();
  gtk_file_filter_add_pattern (ppm_filter, "*.ppm");
  gtk_file_filter_set_name (ppm_filter, "ppm images");
  g_list_store_append (filters, ppm_filter); // Add to the list store
  g_object_unref(ppm_filter); // GListStore takes a reference

  // Create the .bmp filter
  bmp_filter = gtk_file_filter_new ();
  gtk_file_filter_add_pattern (bmp_filter, "*.bmp");
  gtk_file_filter_set_name (bmp_filter, "bmp images");
  g_list_store_append (filters, bmp_filter); // Add to the list store
  g_object_unref(bmp_filter); // GListStore takes a reference

  // Create the 'file load' dialogue  
  file_dialog = gtk_file_dialog_new ();
  gtk_file_dialog_set_filters (file_dialog, G_LIST_MODEL (filters));
  // Set the purpose of the dialog
  gtk_file_dialog_set_title(file_dialog, "Load a Corresction Mask Image");
  // Set the text for the primary action button ("Load").
  gtk_file_dialog_set_accept_label(file_dialog, "Load File");
  g_object_set(file_dialog, "modal", TRUE, NULL); // Ensure it's modal
  // Show the file_dialog
  gtk_file_dialog_open (file_dialog,
                        GTK_WINDOW (Win_main),
                        NULL,
                        (GAsyncReadyCallback) filedlg_callback,
                        GINT_TO_POINTER(FILEDLG_CORR_MASK));

  // Clean up / free the filters list store and file dialog
  g_object_unref(filters);
  g_object_unref(file_dialog); 

 return;
}

void set_mask_full_support(int ht, int wd)
// Set the mask to a full support (non-custom) mask
{
 size_t msize;

  MKht=ht;
  MKwd=wd;
  msize=(size_t)MKht*(size_t)MKwd;
  Mask_supp_size=(double)msize;

  if(resize_memblk((void **)&MaskIm,msize,sizeof(unsigned char), "the mask image")){
   show_message("Generic mask could not be set. No dark field or flat field correction can be done.","MASK FAILED: ",MT_ERR,1);
   mask_alloced=MASK_NO;
   mskfile_loaded = MASK_NONE;
   sprintf(MaskFile,"[None]");
  } else mask_alloced=MASK_YES;   
 // If mem alloced OK we can use the all-permissive mask.
 memset(MaskIm, 255, msize*sizeof(unsigned char));

 sprintf(MaskFile,"[Full]");
 mskfile_loaded = MASK_FULL;
 mask_status = 0;

  return;
}

void nullify_mask(void)
// Nullify the custom corrections mask and set it to full support.
{
 // Re-initialise the mask to be all 255 across the whole field using
 // Selected_Ht and Selected_Wd as dimensions:
 set_mask_full_support(Selected_Ht,Selected_Wd);

  // GUI stuff - don't do this if the camera settings window is not
  // visible because the dynamically allocated GUI controls will not be
  // addressable and GTK errors will result. This situation may arise
  // during the running of a script if the camera settings window was
  // closed prior to running it.
  if(gtk_widget_is_visible(Win_cam_settings)==TRUE){
      gtk_check_button_set_active(GTK_CHECK_BUTTON(chk_usemskcor),FALSE);
      gtk_widget_set_sensitive (chk_usemskcor,FALSE);
      gtk_label_set_text(GTK_LABEL(CamsetWidget[windex_um]),"No");
      gtk_widget_set_sensitive (CamsetWidget[windex_um],FALSE);
      gtk_widget_set_sensitive (CamsetWidget[windex_um2],FALSE);
      // Set label to show nullified filename
      gtk_label_set_text(GTK_LABEL(CamsetWidget[windex_rmski]), MaskFile);  
    }
  if(mask_pending) show_message("Any pre-existing mask image has been nullified. Custom masking is disabled till a new mask image is loaded.","FYI: ",MT_INFO,1);
  return;
}

void set_mask_pending(void)
{
 if(!strcmp(PrevStat.Selected_Mask_filename,"[None]") || !strcmp(PrevStat.Selected_Mask_filename,"[Full]") || !strcmp(PrevStat.Selected_Mask_filename,"[UNDF]")){
   mask_pending=0;
 } else mask_pending=1;
}

static int init_mask_image(void)
// Load any user-specified mask file and get it ready for use. Check the
// format and dimensions, etc.
// Return 0 on success and the loaded mask is present in MaskIm.
// Return 1 on failure and MaskIm is set to full support.
{
 int lht,lwd,imfmt,idx,rgbpos,width_stride;
 unsigned char *tmploc;
 double d1,d2,d3;
 int msupp;
 size_t imsz,rgbimsz;
 char msgtxt[MSGTXT_LEN];
 unsigned char cref[1024];    
 int16_t bitcount;

 if(!strcmp(PrevStat.Selected_Mask_filename,"[None]") || !strcmp(PrevStat.Selected_Mask_filename,"[Full]") || !strcmp(PrevStat.Selected_Mask_filename,"[UNDF]")){
   mask_pending=0;
   if(gtk_widget_is_visible(Win_cam_settings)==TRUE){
     gtk_check_button_set_active(GTK_CHECK_BUTTON(chk_usemskcor),FALSE);
     gtk_widget_set_sensitive (chk_usemskcor,FALSE);
     gtk_widget_set_sensitive (CamsetWidget[windex_um],FALSE);
     gtk_widget_set_sensitive (CamsetWidget[windex_um2],FALSE);
    }
   return 0;
 }

 // Read the mask image file header to get dimensions and file type
 if(!get_pgm_header(PrevStat.Selected_Mask_filename, &lht,&lwd))     imfmt=SAF_YP5;  // PGM greyscale 
 else if(!get_ppm_header(PrevStat.Selected_Mask_filename, &lht,&lwd))imfmt=SAF_RGB;  // PPM colour
 else if(!get_bmp_header(PrevStat.Selected_Mask_filename, &lht,&lwd,&bitcount)){     // BMP
    switch(bitcount){
        case 8: imfmt=SAF_BM8; break;     // greyscale bmp
        case 24:imfmt=SAF_BMP; break;     // colour    bmp  
        default:
             show_message("Selected mask bmp image is not 8 or 24 bit (other bit depths are not supported). Cannot proceed.","FAILED: ",MT_ERR,1);
             nullify_mask(); return 1;
      }   
 } else { // It is not one of the allowed unsigned char formats
         show_message("Selected mask image is not of an acceptable format. No custom masking can be done. Try selecting another file.","FAILED: ",MT_ERR,1);
         nullify_mask(); return 1;
        }

  switch(imfmt){
    case SAF_YP5:
    case SAF_BM8:
     width_stride=Selected_Wd;
    break;
    case SAF_RGB:
    case SAF_BMP:
     width_stride=Selected_Wd*3;
    break;
    default: // This should not happen
        show_message("Unrecognised image format for mask image.","Program Error: ",MT_ERR,1);
        nullify_mask();
        return 1;
    }

 // Check dimensions are identical to current main image
 if(lht!=Selected_Ht){
    show_message("Selected mask image is not the same height as main image. Cannot proceed.","FAILED: ",MT_ERR,1);
    nullify_mask(); return 1;
   }     
 if(lwd!=Selected_Wd){
    show_message("Selected mask image is not the same width as main image. Cannot proceed.","FAILED: ",MT_ERR,1);
    nullify_mask(); return 1;
   }     

 // OK, now see if we can allocate memory for the mask image

 imsz=(size_t)Selected_Ht*(size_t)Selected_Wd; 
 if(resize_memblk((void **)&MaskIm,imsz,sizeof(unsigned char), "the mask image"))
  {
   nullify_mask();
   return 1;
  }

 // We got memory for the mask. Now get memory for a temporary array to
 // load the mask image and try reading the image into it
 rgbimsz=(size_t)Selected_Ht*(size_t)width_stride; 
 tmploc=calloc(rgbimsz,sizeof(unsigned char));
 if(tmploc==NULL){
     show_message("Failed to allocate memory to store mask image. Cannot proceed to load it.","FAILED: ",MT_ERR,1);
     nullify_mask(); return 1;
    }

 // We got memory, so now try reading the image into it
 snprintf(msgtxt,sizeof(msgtxt),"There was a problem reading the chosen mask file. Cannot proceed.");
 switch(imfmt){
        case SAF_YP5: 
            if(get_pgm(PrevStat.Selected_Mask_filename, &tmploc, &lht,&lwd)){
              show_message(msgtxt,"FAILED: ",MT_ERR,1);
              nullify_mask(); free(tmploc); return 1;
            }
        break;
        case SAF_BM8: 
            if(get_bmp(PrevStat.Selected_Mask_filename, &tmploc, &lht, &lwd, cref)){
              show_message(msgtxt,"FAILED: ",MT_ERR,1);
              nullify_mask(); free(tmploc); return 1;
            }
        break;
        case SAF_RGB:
            if(get_ppm(PrevStat.Selected_Mask_filename, &tmploc)){
              show_message(msgtxt,"FAILED: ",MT_ERR,1);
              nullify_mask(); free(tmploc); return 1;
            }
        break;
        case SAF_BMP:
            if(get_bmp(PrevStat.Selected_Mask_filename, &tmploc, &lht, &lwd, cref)){
              show_message(msgtxt,"FAILED: ",MT_ERR,1);
              nullify_mask(); free(tmploc); return 1;
            }
        break;
        default: // This should not happen
         show_message("Unrecognised image format for mask image.","Program Error: ",MT_ERR,1);
         nullify_mask(); free(tmploc); return 1;
    }

 // Now convert the mask image into a binary unsigned char array
 // whatever the original file format was by thresholding at a pixel
 // value of 127.
 msupp=0;
 switch(imfmt){
    case SAF_YP5:
    case SAF_BM8:
      for(idx=0;idx<(int)imsz;idx++){
         if(tmploc[idx]>127){ MaskIm[idx]=255; msupp++;}
         else MaskIm[idx]=0;
       }
    break;
    case SAF_RGB:
    case SAF_BMP:
      for(idx=0,rgbpos=0;idx<(int)imsz;idx++,rgbpos+=3){
         d1=(double)tmploc[rgbpos];
         d2=(double)tmploc[rgbpos+1];
         d3=(double)tmploc[rgbpos+2];
         d1=(d1+d2+d3)/3.0; // Intensity         
         if(d1>127.0){ MaskIm[idx]=255; msupp++;}
         else MaskIm[idx]=0;
       }
    break;
    default: // This can't happen - we checked above
    break;
  }

 // we're done with the temporary array now so free it
 free(tmploc);

 // Check that the mask has at least 1 pixel that is non-zero:
 if(msupp==0){
   show_message("Chosen mask has no support so cannot be used.","FAILED: ",MT_ERR,1);
   nullify_mask(); return 1;
  }

 // Now we set the dimensions and GUI:
 MKht=lht; MKwd=lwd;
 Mask_supp_size=(double)msupp;
 sprintf(MaskFile,"%s",PrevStat.Selected_Mask_filename);
 snprintf(msgtxt,sizeof(msgtxt),"Mask image loaded: %s",MaskFile);
 show_message(msgtxt,"FYI: ",MT_INFO,0);
 mask_alloced=MASK_YES;
 mskfile_loaded=MASK_YRGB;
 
 if(gtk_widget_is_visible(Win_cam_settings)==TRUE){
     //set label to show filename
     gtk_label_set_text(GTK_LABEL(CamsetWidget[windex_rmski]), name_from_path(MaskFile));  
     gtk_widget_set_sensitive (chk_usemskcor,TRUE);
     gtk_widget_set_sensitive (CamsetWidget[windex_um],TRUE);
     gtk_widget_set_sensitive (CamsetWidget[windex_um2],TRUE);
  }
 
 return 0;
}

