                     snprintf(msgtxt,sizeof(msgtxt),"%-7s",gtk_editable_get_text(GTK_EDITABLE(CamsetWidget[ctrlindex])));
                     tmp_avd=atoi(msgtxt);
                     // Check this value is within acceptable limits
                     // hard coded here as 1 to 604800 (arbitrary limit,
