static void hide_remove_from_container(GtkWidget *widget, GtkGrid *grid)
{
 gpointer combo_ptr;

 // 1. Defensive Fence: Abort if the widget pointer or grid reference is null
 if (widget == NULL || grid == NULL) return;

 // 2. Object Integrity Fence: Verify this is a genuine, active GTK widget
 if (!GTK_IS_WIDGET(widget)) return;

 // =========================================================================
 // HARDENING GATE: THE PARENT ARCHITECTURE CHECK
 // =========================================================================
 // Only attempt to remove the widget from the layout cell matrix if the widget
 // actively belongs to this specific grid parent container! If it doesn't,
 // we skip the removal entirely, preventing the fatal parent-assertion crash.
 if (gtk_widget_get_parent(widget) != GTK_WIDGET(grid)) {
     // The widget was never attached due to a midway constructor failure.
     // Safely hide it and exit non-destructively to protect the heap tables.
     gtk_widget_set_visible(widget, FALSE);
     return;
 }
 // =========================================================================

 gtk_widget_set_visible(widget,FALSE);          // Hide the widget
 // Get the reference of the widget because gtk_grid_remove will loose the
 // reference of the argument passed to it (and it will effectively be destroyed
 // so can't be used again.)
 combo_ptr = g_object_ref(widget); 
 // Remove the widget from the grid (may need to be placed in a different cell
 // if a different set of settings is constructed (e.g. from another camera).
 gtk_grid_remove (grid,GTK_WIDGET(combo_ptr)); 
 return;
}

static gboolean on_camset_close_request(GtkWindow *window, gpointer data)
{
 int ctrlindex;
 GtkStringList *list_model;
 static gboolean cleaning_in_progress = FALSE;

 if(cleaning_in_progress) return TRUE; // Abort second pass immediately!
 cleaning_in_progress = TRUE;


 // Ensure the interactive slider is not assigned to a control:
   IScidx=-1; // Camera settings structure for interactive control
   ISwindex=-1;// Edit box widget index for GUI interactive updates
   gtk_label_set_text (GTK_LABEL(ISLabel),"Real-time control of: [None - select a control edit box below]");
   gtk_adjustment_set_value (ISlider_params,0);
   gtk_adjustment_set_step_increment (ISlider_params,1.0);


 // Clear the entries from the size combo (or you will get duplicate
 // entries next time you open the settings window (we use 'append' to
 // add entries). We do this before destroying the text widgets to avoid
 // errors of calling out to non-existent text label widgets
 // 1. Get the current model from the dropdown
 list_model = GTK_STRING_LIST(gtk_drop_down_get_model(Combo_sz));
 // Ensure the model is actually a GtkStringList and not NULL
 if (list_model != NULL) {
     // 2. Remove all items from the start (index 0) up to the number of items currently in the list
     guint num_items = g_list_model_get_n_items(G_LIST_MODEL(list_model));
     if (list_model != NULL) num_items = g_list_model_get_n_items(G_LIST_MODEL(list_model));
     if (num_items > 0) for (guint i = 0; i < num_items; i++) {
        gtk_string_list_remove(list_model, 0); 
      }
  }

 // First delete text in edit boxes - needed otherwise there are "pango"
 // run-time critical warnings of the type: Pango-CRITICAL **:
 // pango_layout_get_cursor_pos: assertion 'index >= 0 && index <=
 // layout->length' failed
 // If control widgets were created, look for those with edit boxes and
 // delete the edit box text
  if(windex){ 
   char clstr[5];
   sprintf(clstr, "    ");
   for(ctrlindex=0;ctrlindex<windex;ctrlindex++){
       GtkWidget *child = CamsetWidget[ctrlindex];
       if(!GTK_IS_WIDGET(child)){
         ctrl_id[ctrlindex] = 0;
         cswt_id[ctrlindex] = CS_WTYPE_UNDEF;
         continue; 
       }
       switch(cswt_id[ctrlindex]){
           case CS_WTYPE_ENTRY:
            gtk_editable_delete_text(GTK_EDITABLE(child), 0, -1);
            if(gtk_widget_get_parent(child) == GTK_WIDGET(Grid_camset)){
               gtk_grid_remove(GTK_GRID(Grid_camset), child);
              }
            break;
           case CS_WTYPE_LABEL:
            gtk_label_set_text(GTK_LABEL(child), clstr);
            if (gtk_widget_get_parent(child) == GTK_WIDGET(Grid_camset)) {
                gtk_grid_remove(GTK_GRID(Grid_camset), child);
            }
           break;
           default: break;
        }
        CamsetWidget[ctrlindex] = NULL;
        ctrl_id[ctrlindex]=0; // means it does not contain valid entries
        cswt_id[ctrlindex]=CS_WTYPE_UNDEF;
      }
   windex = 0;
  }

  // Unfade settings button on main window (if we are not in a delayed
  // start countdown):
  if(!Delayed_start_in_progress)
  gtk_widget_set_sensitive (GTK_WIDGET(data),TRUE); 
  // Hide the apply button. No need to remove from grid because it
  // always stays in the same cell:
  gtk_widget_set_visible(btn_cs_apply,FALSE); 
  gtk_widget_set_visible(btn_cs_apply_nc,FALSE); 
  
  // Hide and remove the size selector combo
  hide_remove_from_container(GTK_WIDGET(Combo_sz),GTK_GRID(Grid_camset));
  // Hide the preview size selector combo
  hide_remove_from_container(GTK_WIDGET(Combo_psz),GTK_GRID(Grid_camset)); 
  // Hide the preview fps selector combo
  hide_remove_from_container(GTK_WIDGET(Combo_fps),GTK_GRID(Grid_camset)); 
  // Hide the preview LUT selector combo
  hide_remove_from_container(GTK_WIDGET(Combo_plut),GTK_GRID(Grid_camset)); 
  // Hide the save as format selector combo
  hide_remove_from_container(GTK_WIDGET(Combo_camfmt),GTK_GRID(Grid_camset));
  // Hide the save as format selector combo 
  hide_remove_from_container(GTK_WIDGET(Combo_safmt),GTK_GRID(Grid_camset)); 
  // Hide the preview crop window selector check box
  hide_remove_from_container(chk_preview_central,GTK_GRID(Grid_camset)); 
  // Hide the preview monochrome window selector check box
  hide_remove_from_container(chk_cam_yonly,GTK_GRID(Grid_camset)); 
  // Hide the use save as raw doubles selector check box
  hide_remove_from_container(chk_sa_rawdoubles,GTK_GRID(Grid_camset)); 
  // Hide the use save as FITS selector check box
  hide_remove_from_container(chk_sa_fits,GTK_GRID(Grid_camset)); 
  // Hide the Scale mean of each frame to first? selector check box
  hide_remove_from_container(chk_scale_means,GTK_GRID(Grid_camset)); 
  // Hide the Use cumulative histogram (Red/Grey)? selector check box
  hide_remove_from_container(chk_usehcr,GTK_GRID(Grid_camset)); 
  // Hide the Use cumulative histogram (Green)? selector check box
  hide_remove_from_container(chk_usehcg,GTK_GRID(Grid_camset)); 
  // Hide the Use cumulative histogram (Blue)? selector check box
  hide_remove_from_container(chk_usehcb,GTK_GRID(Grid_camset)); 
  // Hide the Don't auto-fit histograms? selector check box
  hide_remove_from_container(chk_hgm_manual,GTK_GRID(Grid_camset)); 
  // Hide the Variance and mean restricted to sat limits? selector check box
  hide_remove_from_container(chk_var_inlimits,GTK_GRID(Grid_camset)); 
  // Hide the Focusser use variance x abs. Laplacian? selector check box
  hide_remove_from_container(chk_usefov,GTK_GRID(Grid_camset)); 
  // Hide the Pre-Laplacian median filter? selector check box
  hide_remove_from_container(chk_useprm,GTK_GRID(Grid_camset)); 
  // Hide the Post-Laplacian median filter? selector check box
  hide_remove_from_container(chk_usepom,GTK_GRID(Grid_camset)); 
  // Hide the Calc. DCT after LUT transform? selector check box
  hide_remove_from_container(chk_usedal,GTK_GRID(Grid_camset)); 
  // Hide the Display Laplacian? selector check box
  hide_remove_from_container(chk_useppl,GTK_GRID(Grid_camset)); 
  // Hide the Invert? selector check box
  hide_remove_from_container(chk_useppi,GTK_GRID(Grid_camset)); 
  // Hide the Flip horizontal? selector check box
  hide_remove_from_container(chk_usefph,GTK_GRID(Grid_camset)); 
  // Hide the Flip vertical? selector check box
  hide_remove_from_container(chk_usefpv,GTK_GRID(Grid_camset)); 
  // Hide the Focusser Use discrete cosine transform? selector check box
  hide_remove_from_container(chk_usefds,GTK_GRID(Grid_camset)); 
  // Hide the Focusser use absolute Laplacian? selector check box
  hide_remove_from_container(chk_usefls,GTK_GRID(Grid_camset)); 
  // Hide the use preview mask selector check box 
  hide_remove_from_container(chk_usepmsk,GTK_GRID(Grid_camset)); 
  // Hide the show preview mask selector check box 
  hide_remove_from_container(chk_dsppmsk,GTK_GRID(Grid_camset)); 
  // Hide the preview mask file selector button
  hide_remove_from_container(btn_cs_load_pmsk,GTK_GRID(Grid_camset)); 
  // Hide the use preview colour dark selector check box 
  hide_remove_from_container(chk_usepcd,GTK_GRID(Grid_camset)); 
  // Hide the preview colour dark file selector button
  hide_remove_from_container(btn_cs_load_pcd,GTK_GRID(Grid_camset)); 
  // Hide the use dark field correction selector check box
  hide_remove_from_container(chk_usedfcor,GTK_GRID(Grid_camset)); 
  // Hide the dark field correction reference file selector button
  hide_remove_from_container(btn_cs_load_dfri,GTK_GRID(Grid_camset));
  // Hide the use flat field correction selector check box 
  hide_remove_from_container(chk_useffcor,GTK_GRID(Grid_camset)); 
  // Hide the flat field correction reference file selector button
  hide_remove_from_container(btn_cs_load_ffri,GTK_GRID(Grid_camset)); 
  // Hide the use correction mask selector check box 
  hide_remove_from_container(chk_usemskcor,GTK_GRID(Grid_camset)); 
  // Hide the correction mask file selector button
  hide_remove_from_container(btn_cs_load_mskri,GTK_GRID(Grid_camset)); 
  // Hide the load settings file selector button
  hide_remove_from_container(btn_cs_load_cset,GTK_GRID(Grid_camset)); 
  // Hide the save settings file selector button
  hide_remove_from_container(btn_cs_save_cset,GTK_GRID(Grid_camset)); 

  gtk_widget_set_visible(GTK_WIDGET(window),FALSE);  // Finally, hide the settings window itself.
  cleaning_in_progress = FALSE; 
  return TRUE;
}

void update_preview_mono_integral_bias(gint ival, gint adjtype)
{
 char msgtxt[MSGTXT_LEN];
 int idx;

 switch(adjtype){
  case PADJUST_INTEGRAL:
   snprintf(msgtxt,sizeof(msgtxt),"Integrating %d frames for preview",ival);
   show_message(msgtxt,"FYI: ",MT_INFO,0);
   if(ival>1){
     for(idx=1;idx<ival;idx++){
       if(resize_memblk((void **)&PreviewBuff[idx],(size_t)PreviewImg_size,
                                         sizeof(int), "the integration buffer"))
        {
         show_message("No RAM available for prime preview buffer.","Error: ",
                                                                      MT_ERR,0);
         Preview_integral=1;
         return;
        }
      }
     if(idx<PREVINTMAX){ // De-alloc memory from unused preview buffers
       for(;idx<PREVINTMAX;idx++){
         if(resize_memblk((void **)&PreviewBuff[idx],(size_t)1,sizeof(int),
                                                      "the integration buffer"))
          {
           show_message("No RAM available to de-alloc prime preview buffer.",
                                                            "Error: ",MT_ERR,0);
           Preview_integral=1;
           return;
          }
        }
      }
    }

   Preview_integral=ival;
  break;
  case PADJUST_BIAS:
   snprintf(msgtxt,sizeof(msgtxt),"Biasing preview by %d greyscale units",ival);
   show_message(msgtxt,"FYI: ",MT_INFO,0);
   Preview_bias=ival;
  break;
  default: // Shouldn't get here - programming error
   show_message("Unrecognised preview adjust constant.","Program Error: ",
                                                                      MT_ERR,0);
  break;
 }

 return;
}

static void grab_prev_adjust_value (GtkSpinButton *button, gpointer padjtype)
{
 gint ival,adjtype;
 ival = gtk_spin_button_get_value_as_int (button);
 adjtype = GPOINTER_TO_INT(padjtype);
 update_preview_mono_integral_bias(ival,adjtype);
 return;
}

static void close_cam_with_query(char *query_message, int just_close)
{
 int caller;
 GtkAlertDialog *dlg_choice;
 dlg_choice = gtk_alert_dialog_new("Close Camera?");
 gtk_alert_dialog_set_buttons(dlg_choice, YNbuttons);
 gtk_alert_dialog_set_default_button(dlg_choice, 1);
 gtk_alert_dialog_set_detail(GTK_ALERT_DIALOG(dlg_choice), query_message);
 Just_close=just_close;
 caller = (just_close)?CHOICE_CLOSE_CAMERA:CHOICE_CHANGE_CAMERA;
 
 // Show the dialog asynchronously
 gtk_alert_dialog_choose (GTK_ALERT_DIALOG(dlg_choice),
                          GTK_WINDOW (Win_main),
                          NULL, // cancellable
                          (GAsyncReadyCallback) on_choice_response,
                          GINT_TO_POINTER(caller));
 return;
}

static void combo_vnum_selected(GtkWidget * combovn, GdkEvent * event, gpointer data)
{
 const char *numstr=NULL;
 int idx=0; // (14.11.26) initialised: it was used uninitialised below when
            // the list text could not be read (the 'Defaulting to 0' case)

 numstr = get_selected_dropdown_item_str(
                       gtk_drop_down_get_selected_item(GTK_DROP_DOWN(combovn)));
 if(numstr != NULL){
    sscanf(numstr,"%d",&idx);
    g_free((gpointer)numstr);
  } else {
    show_message("Error reading device number from the list.\nDefaulting to 0.",
                                                            "Error: ",MT_ERR,1);
    DevNum = 0;
  }

 DevNum=idx;

 set_dev_name_from_devnum(); // (14.11.26) "/dev/videoN" on Linux

 printf("\nSelecting device: %s\n",Dev_Name);

 return;
}

