static gboolean key_press_event_wm_gtk4(
    GtkEventControllerKey *controller,
    guint keyval,      // The GDK key value (e.g., GDK_KEY_a, GDK_KEY_Escape)
    guint keycode,     // The hardware key code
    GdkModifierType state, // Modifier flags (e.g., GDK_SHIFT_MASK)
    gpointer user_data
) 
{
  // Take action according to what key is pressed
  switch (keyval) {
        case GDK_KEY_g: // Grab ('Save Image') button activate
            if(TRUE==gtk_widget_get_sensitive (btn_cam_save)){
              show_message("g key pressed - activating 'Save image' button.","FYI: ",MT_INFO,0);
              btn_cam_save_click(btn_cam_save,btn_cam_save);
             }
        return TRUE;
        case GDK_KEY_a: // Audio on/off toggle
            if (gtk_check_button_get_active(GTK_CHECK_BUTTON(chk_audio))){
                gtk_check_button_set_active(GTK_CHECK_BUTTON(chk_audio),FALSE);
                Use_audio=AU_NO;
             } else {
                gtk_check_button_set_active(GTK_CHECK_BUTTON(chk_audio),TRUE);
                Use_audio=AU_YES;
             }
        return TRUE;
        case GDK_KEY_c: // Close camera
             if(camera_status.cs_opened){
               close_cam_with_query("Do you really want to close the camera connection?",1);
             }
        return TRUE;
        case GDK_KEY_v: // Select video device
             // If the camera is open, ask if they want to close it first
             if(camera_status.cs_opened){
               // The callback in this asynchronous dialog will also allow them
               // to change the camera once the close it so we do the effect_
               // camera_change_request() on an 'else' branch below to pick up
               // the case where the camera is not open when the 'v' key is
               // pressed.
               close_cam_with_query("This action will close the current camera connection. Do you want to proceed?",0);
             } else effect_camera_change_request();
        return TRUE;
        case GDK_KEY_bracketleft:  // Move the histogram overlay position
             if(Prev_overlay_hgm){
               if(PrevStat.hgm_origin_x > 2) PrevStat.hgm_origin_x -= 38;
               else {
                  PrevStat.hgm_origin_x = 382;
                  if(PrevStat.hgm_origin_y > 2) PrevStat.hgm_origin_y-=22;
                  else PrevStat.hgm_origin_y = 222;
                 }
               if(!Prev_aspect_4_by_3 && Need_to_preview)
                memset(PreviewImg, 127, PreviewImg_rgb_size*sizeof(unsigned char));
              }
        return TRUE;
        case GDK_KEY_bracketright: // Move the histogram overlay position
             if(Prev_overlay_hgm){
               PrevStat.hgm_origin_x += 38;
               if(PrevStat.hgm_origin_x > 382){
                  PrevStat.hgm_origin_x=2;
                  PrevStat.hgm_origin_y += 22;
                  if(PrevStat.hgm_origin_y > 222) PrevStat.hgm_origin_y=2;
                 }
               if(!Prev_aspect_4_by_3 && Need_to_preview)
                memset(PreviewImg, 127, PreviewImg_rgb_size*sizeof(unsigned char));
              }
        return TRUE;
        case GDK_KEY_equal: // Toggle the focusser overlay position
             if(Prev_overlay_focus){
               if(PrevStat.focus_origin_y > Focusser_y_up)
                 PrevStat.focus_origin_y = Focusser_y_up;
                 else PrevStat.focus_origin_y = Focusser_y_down;
                
               if(!Prev_aspect_4_by_3 && Need_to_preview)
                memset(PreviewImg, 127, PreviewImg_rgb_size*sizeof(unsigned char));
              }
        return TRUE;
        case GDK_KEY_h:
             show_message("Press the 'g' key to activate the 'Save Image' button","Help: ",MT_INFO,0);
             show_message("Press the 'a' key to toggle audio signals on/off","Help: ",MT_INFO,0);
             show_message("Press the 'c' key to close the camera connection","Help: ",MT_INFO,0);
             show_message("Press the 'v' key to select a video device","Help: ",MT_INFO,0);
             show_message("Press the '[' or ']' keys to move the preview overlay","Help: ",MT_INFO,0);
             show_message("Press the '=' key to toggle the focus bar to top/bottom of the overlay","Help: ",MT_INFO,0);
        return TRUE;
        default:
        break;
    }

    return FALSE;
}

static gboolean on_mainwin_show (GtkWidget *widget, GdkEvent  *event,  gpointer   data)
{
 if(Log_wanted == -1){
   // We must use show_popup directly - not show_message - because the
   // gui_up flag will not have been set at this point (so you won't see
   // a popup window even though you request it) and also this
   // Log_wanted flag needs to be 0 or 1 for proper log handling in the
   // show_message function.
   show_popup("Failed to initialise a log file for this session.\n","ERROR: ");
   Log_wanted=0;
  }
 return TRUE;
}

static gboolean on_close_request (GtkWindow *window,  gpointer data)
{
 GtkAlertDialog *dlg_choice;
 
 // Enforced a clean literal string format mask to protect constructor tracking.
 dlg_choice = gtk_alert_dialog_new("%s", "Quit PARDcap?");
 
 // Added an explicit instance guard gate to capture initialization drops cleanly
 if (dlg_choice == NULL) {
     return TRUE; // Safely aborts the destruction pass if a widget build drops out
 }

 gtk_alert_dialog_set_buttons(dlg_choice, YNbuttons);
 gtk_alert_dialog_set_default_button(dlg_choice, 1);

 // State tracking updates specific to the pardcap image server pipeline
 ps_Suspend_timeout=1;
 Tmprevstatus=Need_to_preview;
 Need_to_preview=PREVIEW_OFF;
 if(ps_Pbar_initiated) ps_pollbar(PS_PB_TERMINATE);

 // FIXED: Corrected typo inside log string block
 show_message("Close request occurred.","\nNotice!: ",MT_INFO,0);

 // Ask if sure they want to quit. If 'Yes' then return FALSE otherwise (to stay running) return TRUE
 gtk_alert_dialog_set_detail(GTK_ALERT_DIALOG(dlg_choice), "Do you really want to quit?");
 
 // Show the dialog asynchronously using the proper callback handler mapping
 gtk_alert_dialog_choose (GTK_ALERT_DIALOG(dlg_choice),
                           GTK_WINDOW (Win_main),
                           NULL, // cancellable
                           (GAsyncReadyCallback) on_choice_response,
                           GINT_TO_POINTER(CHOICE_QUIT_PROGRAM));

 return TRUE;
}

static void add_button(GtkWidget **btn,const gchar *label,GtkAlign align)
// Create a new button widget using the supplied parameters
{
  *btn = gtk_button_new_with_label (label);
  gtk_widget_set_size_request(*btn,bt_def_wd,32);
  gtk_widget_set_hexpand (*btn, FALSE);
  gtk_widget_set_halign (*btn, align);
}

static void add_win(GtkWidget **win,GtkApplication* app, const gchar *title,gint wd, gint ht,gboolean sizeable, gboolean modal)
// Create a new window widget using the supplied parameters
{
 *win = gtk_application_window_new (app);
 gtk_window_set_title (GTK_WINDOW (*win), title);
 gtk_window_set_default_size(GTK_WINDOW(*win), wd, ht);
 gtk_window_set_resizable (GTK_WINDOW(*win),sizeable);
 gtk_window_set_modal (GTK_WINDOW(*win),modal);
}

static void add_grid(GtkGrid **grd, GtkWidget **ctn)
// Create a new grid using the supplied parameters
 {
 // We assume 'ctn' points to a GtkWindow or another single-child container.
 // GtkWindow implements GtkRoot which has a set_child function.
 
 // Create the new grid
 *grd = GTK_GRID(gtk_grid_new());  
 
 // Set spacing (these functions are still valid in GTK4)
 gtk_grid_set_row_spacing(GTK_GRID(*grd), 2);
 gtk_grid_set_column_spacing(GTK_GRID(*grd), 2);

 // In GTK4, use gtk_window_set_child() instead of gtk_container_add()
 // if *ctn is meant to be a window.
 // If *ctn is a different container (like a GtkBox), you would use gtk_box_append().
 
 if (GTK_IS_WINDOW(*ctn)) {
     // Use gtk_window_set_child if the container is a window
     gtk_window_set_child(GTK_WINDOW(*ctn), GTK_WIDGET(*grd));
 } 
 // You could add else if blocks for GtkBox, GtkScrolledWindow, etc., 
 // depending on the intended use of *ctn.
}

static void add_checkbox(GtkWidget **cbox)
// Create a new check box
{
 *cbox = gtk_check_button_new();
 gtk_check_button_set_active(GTK_CHECK_BUTTON(*cbox), FALSE);
 gtk_widget_set_halign (*cbox, GTK_ALIGN_CENTER);
}

